/// A thread-safe cancellation signal for synchronous facade operations.
///
/// Cancelling a token wakes the async CDP wait owned by a synchronous call, so
/// the owner thread can return without waiting for the operation timeout.
#[derive(Clone, Debug, Default)]
pub struct CancelToken {
    inner: Arc<CancelTokenInner>,
}

#[derive(Debug, Default)]
struct CancelTokenInner {
    cancelled: Arc<AtomicBool>,
    physical_action_state: AtomicU8,
    physical_action_ever_committed: AtomicBool,
    changed: tokio::sync::Notify,
}

const PHYSICAL_ACTION_ACTIVE: u8 = 0;
const PHYSICAL_ACTION_CANCELLED: u8 = 1;
const PHYSICAL_ACTION_COMMITTED: u8 = 2;

impl CancelToken {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn cancel(&self) {
        let _ = self.try_cancel();
    }

    /// Attempt to cancel before a physical input action commits.
    ///
    /// Returns `false` if cancellation already won or physical dispatch has
    /// committed, making the cancellation boundary atomic for callers that
    /// need to report whether cancellation took effect. The persistent
    /// cancellation signal is recorded either way so this token remains
    /// cancelled for later operations.
    pub fn try_cancel(&self) -> bool {
        if !self.inner.cancelled.swap(true, Ordering::SeqCst) {
            self.inner.changed.notify_waiters();
        }
        let won_physical_action_arbitration = self
            .inner
            .physical_action_state
            .compare_exchange(
                PHYSICAL_ACTION_ACTIVE,
                PHYSICAL_ACTION_CANCELLED,
                Ordering::SeqCst,
                Ordering::SeqCst,
            )
            .is_ok();
        won_physical_action_arbitration
    }

    /// Whether cancellation has ever been requested for this token.
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.load(Ordering::SeqCst)
    }

    /// Whether any physical input action has crossed its cancellation boundary.
    ///
    /// This observation remains true for request-level result ownership. The
    /// separate per-action arbitration state is reset after each dispatch.
    pub fn is_physical_action_committed(&self) -> bool {
        self.inner
            .physical_action_ever_committed
            .load(Ordering::SeqCst)
    }

    fn commit_physical_action(&self) -> bool {
        let committed = self
            .inner
            .physical_action_state
            .compare_exchange(
                PHYSICAL_ACTION_ACTIVE,
                PHYSICAL_ACTION_COMMITTED,
                Ordering::SeqCst,
                Ordering::SeqCst,
            )
            .is_ok();
        if committed {
            self.inner
                .physical_action_ever_committed
                .store(true, Ordering::SeqCst);
        }
        committed
    }

    fn begin_physical_action(&self) -> RwResult<PhysicalActionCommitGuard<'_>> {
        if self.is_cancelled() || !self.commit_physical_action() {
            return Err(RwError::Cancelled);
        }
        Ok(PhysicalActionCommitGuard { token: self })
    }

    fn atomic_flag(&self) -> Arc<AtomicBool> {
        Arc::clone(&self.inner.cancelled)
    }

    async fn cancelled(&self) {
        loop {
            if self.is_cancelled() {
                return;
            }
            let changed = self.inner.changed.notified();
            if self.is_cancelled() {
                return;
            }
            changed.await;
        }
    }
}

struct PhysicalActionCommitGuard<'a> {
    token: &'a CancelToken,
}

impl Drop for PhysicalActionCommitGuard<'_> {
    fn drop(&mut self) {
        let reset = self.token.inner.physical_action_state.compare_exchange(
            PHYSICAL_ACTION_COMMITTED,
            PHYSICAL_ACTION_ACTIVE,
            Ordering::SeqCst,
            Ordering::SeqCst,
        );
        debug_assert!(
            reset.is_ok(),
            "only the physical-action committer may reset its arbitration state"
        );
    }
}

async fn dispatch_committed_physical_action<T, Fut>(
    cancel: Option<&CancelToken>,
    dispatch: Fut,
) -> RwResult<T>
where
    Fut: Future<Output = RwResult<T>>,
{
    let _commit = cancel.map(CancelToken::begin_physical_action).transpose()?;
    dispatch.await
}

async fn cancelable<T, Fut>(token: Option<CancelToken>, future: Fut) -> RwResult<T>
where
    Fut: Future<Output = RwResult<T>>,
{
    let Some(token) = token else {
        return future.await;
    };
    tokio::select! {
        biased;
        () = token.cancelled() => Err(RwError::Cancelled),
        result = future => result,
    }
}

async fn cancelable_navigation<T, Fut>(
    client: Arc<CdpClient>,
    session_id: String,
    token: Option<CancelToken>,
    future: Fut,
) -> RwResult<T>
where
    Fut: Future<Output = RwResult<T>>,
{
    let Some(token) = token else {
        return future.await;
    };
    tokio::select! {
        biased;
        () = token.cancelled() => {
            let _ = tokio::time::timeout(
                Duration::from_millis(100),
                client.send(
                    "Page.stopLoading",
                    json!({}),
                    Some(&session_id),
                    Duration::from_millis(100),
                ),
            )
            .await;
            Err(RwError::Cancelled)
        }
        result = future => result,
    }
}

#[derive(Clone, Debug)]
struct CloseOutcome {
    error: Option<String>,
}

impl CloseOutcome {
    fn from_result(result: &RwResult<()>) -> Self {
        Self {
            error: result.as_ref().err().map(ToString::to_string),
        }
    }

    fn into_result(self) -> RwResult<()> {
        self.error
            .map_or(Ok(()), |error| Err(RwError::Message(error)))
    }
}

enum ClosePhase {
    Open,
    Closing(watch::Sender<Option<CloseOutcome>>),
    Closed(CloseOutcome),
}

struct CloseLifecycle {
    phase: Mutex<ClosePhase>,
}

enum CloseStart {
    Lead(watch::Sender<Option<CloseOutcome>>),
    Wait(watch::Receiver<Option<CloseOutcome>>),
    Done(CloseOutcome),
}

impl CloseLifecycle {
    fn new() -> Self {
        Self {
            phase: Mutex::new(ClosePhase::Open),
        }
    }

    fn start(&self) -> CloseStart {
        let mut phase = self.phase.lock().unwrap();
        match &*phase {
            ClosePhase::Open => {
                let (sender, _) = watch::channel(None);
                *phase = ClosePhase::Closing(sender.clone());
                CloseStart::Lead(sender)
            }
            ClosePhase::Closing(sender) => CloseStart::Wait(sender.subscribe()),
            ClosePhase::Closed(outcome) => CloseStart::Done(outcome.clone()),
        }
    }

    fn finish(
        &self,
        sender: watch::Sender<Option<CloseOutcome>>,
        result: &RwResult<()>,
        close_on_error: bool,
    ) {
        let outcome = CloseOutcome::from_result(result);
        {
            let mut phase = self.phase.lock().unwrap();
            if result.is_ok() || close_on_error {
                *phase = ClosePhase::Closed(outcome.clone());
            } else {
                *phase = ClosePhase::Open;
            }
        }
        sender.send_replace(Some(outcome));
    }

    fn is_closed(&self) -> bool {
        matches!(*self.phase.lock().unwrap(), ClosePhase::Closed(_))
    }

    fn is_closing_or_closed(&self) -> bool {
        !matches!(*self.phase.lock().unwrap(), ClosePhase::Open)
    }
}

async fn wait_for_close_outcome(
    mut receiver: watch::Receiver<Option<CloseOutcome>>,
) -> RwResult<()> {
    loop {
        if let Some(outcome) = receiver.borrow().clone() {
            return outcome.into_result();
        }
        receiver
            .changed()
            .await
            .map_err(|_| RwError::Message("close operation ended without a result".to_string()))?;
    }
}

async fn single_flight_close<F, Fut>(
    lifecycle: Arc<CloseLifecycle>,
    close_on_error: bool,
    cleanup: F,
) -> RwResult<()>
where
    F: FnOnce() -> Fut,
    Fut: Future<Output = RwResult<()>>,
{
    match lifecycle.start() {
        CloseStart::Done(outcome) => outcome.into_result(),
        CloseStart::Wait(receiver) => wait_for_close_outcome(receiver).await,
        CloseStart::Lead(sender) => {
            let result = cleanup().await;
            lifecycle.finish(sender, &result, close_on_error);
            result
        }
    }
}

struct PendingCommandGuard {
    id: u64,
    pending: CdpPendingMap,
    outstanding: CdpOutstandingMap,
    traffic_log: Arc<Mutex<CdpTrafficLog>>,
}

struct QueuedCdpCommand {
    method: String,
    timeout: Duration,
    response: oneshot::Receiver<RwResult<Value>>,
    _pending_guard: PendingCommandGuard,
}

impl QueuedCdpCommand {
    async fn wait(self) -> RwResult<Value> {
        match tokio::time::timeout(self.timeout, self.response).await {
            Ok(Ok(result)) => result.map_err(|error| match error {
                RwError::Message(message) => RwError::Cdp {
                    method: self.method,
                    message,
                },
                other => other,
            }),
            Ok(Err(_)) => Err(RwError::Disconnected),
            Err(_) => Err(RwError::Timeout(self.timeout.as_millis() as u64)),
        }
    }
}

struct FocusEmulationEnqueueReceipt {
    session_id: String,
    command: QueuedCdpCommand,
}

impl FocusEmulationEnqueueReceipt {
    fn absorb_response(self) {
        tokio::spawn(async move {
            let _ = self.command.wait().await;
        });
    }
}

struct SpawnedTaskAbortGuard(tokio::task::AbortHandle);

impl PendingCommandGuard {
    fn new(
        id: u64,
        pending: &CdpPendingMap,
        outstanding: &CdpOutstandingMap,
        traffic_log: &Arc<Mutex<CdpTrafficLog>>,
    ) -> Self {
        Self {
            id,
            pending: Arc::clone(pending),
            outstanding: Arc::clone(outstanding),
            traffic_log: Arc::clone(traffic_log),
        }
    }
}

impl Drop for PendingCommandGuard {
    fn drop(&mut self) {
        let was_pending = self.pending.lock().unwrap().remove(&self.id).is_some();
        let outstanding = self.outstanding.lock().unwrap().remove(&self.id);
        if was_pending {
            if let Some(outstanding) = outstanding {
                self.traffic_log
                    .lock()
                    .unwrap()
                    .push(outstanding.traffic_entry("abandoned-without-response"));
            }
        }
    }
}

impl Drop for SpawnedTaskAbortGuard {
    fn drop(&mut self) {
        self.0.abort();
    }
}

const CDP_EVENT_LOG_LIMIT: usize = 8192;
