    #[tokio::test]
    async fn indeterminate_empty_fill_surfaces_once_without_retrying_delete() {
        let (page, mut peer) = input_protocol_page(Some(""));
        peer.fail_next_delete_after_begin = true;
        peer.allow_close = true;
        let (result_tx, result_rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let _ = result_tx.send(page.fill("#target", "", Some(300.0)));
        });

        let deadline = tokio::time::Instant::now() + Duration::from_secs(3);
        let mut commands = Vec::new();
        let result = loop {
            if let Ok(result) = result_rx.try_recv() {
                break result;
            }
            assert!(
                tokio::time::Instant::now() < deadline,
                "public fill did not finish after the tracked write became indeterminate"
            );
            if let Ok(command) =
                tokio::time::timeout(Duration::from_millis(25), peer.next_command()).await
            {
                commands.push(command);
            }
        };

        tokio::time::sleep(Duration::from_millis(75)).await;
        while let Ok(outgoing) = peer.write_rx.try_recv() {
            match outgoing {
                CdpOutgoing::Text {
                    payload, tracker, ..
                } => {
                    if let Some(tracker) = tracker {
                        assert!(tracker.begin_write());
                        tracker.finish(true);
                    }
                    commands.push(
                        serde_json::from_str::<Value>(&payload).expect("valid drained CDP command"),
                    );
                }
                CdpOutgoing::Close => {}
            }
        }
        let error = result.expect_err("indeterminate Delete delivery must surface");
        let RwError::ActionFailure(details) = error else {
            panic!("expected unknown-outcome action failure, got {error:?}");
        };
        assert_eq!(
            details.metadata(),
            &FailureMetadata {
                kind: Some(FailureKind::UnknownOutcome),
                phase: Some(FailurePhase::Dispatch),
                target_kind: Some(FailureTargetKind::Page),
                command_written: Some(CommandWritten::Indeterminate),
                retryable: Some(false),
            }
        );
        assert_eq!(
            commands
                .iter()
                .filter(|command| {
                    command["method"] == "Input.dispatchKeyEvent"
                        && command["params"]["type"] == "rawKeyDown"
                        && command["params"]["key"] == "Delete"
                })
                .count(),
            1,
            "the outer fill loop must not replay an indeterminate Delete"
        );
        assert_eq!(
            commands
                .iter()
                .filter(|command| {
                    command["method"] == "Input.dispatchKeyEvent"
                        && command["params"]["type"] == "keyUp"
                        && command["params"]["key"] == "Delete"
                })
                .count(),
            1,
            "cleanup must release Delete exactly once"
        );
        assert!(
            commands.iter().any(|command| {
                matches!(
                    command["method"].as_str(),
                    Some("Runtime.evaluate" | "Runtime.callFunctionOn")
                ) && input_command_expression(command)
                    .is_some_and(|expression| expression.contains("g.passive = true"))
            }),
            "unknown outcome must passivate the fill guard for late observation"
        );
    }

    #[test]
    fn typing_cancelled_during_final_character_returns_success_without_commit() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .worker_threads(1)
            .build()
            .unwrap();
        let (write_tx, mut write_rx) = mpsc::unbounded_channel();
        let pending = Arc::new(Mutex::new(HashMap::new()));
        let (events, _) = broadcast::channel(4);
        let event_log = Arc::new(Mutex::new(CdpEventLog::new()));
        let (alive_tx, _) = watch::channel(true);
        let client = Arc::new(CdpClient {
            write_tx,
            pending: Arc::clone(&pending),
            outstanding: Arc::new(Mutex::new(HashMap::new())),
            events: events.clone(),
            event_log: Arc::clone(&event_log),
            traffic_log: Arc::new(Mutex::new(CdpTrafficLog::new())),
            runtime_state: Arc::new(Mutex::new(CdpRuntimeState::new(None))),
            next_id: AtomicU64::new(1),
            sent_runtime_enable_count: AtomicU64::new(0),
            sent_target_close_count: AtomicU64::new(0),
            sent_context_dispose_count: AtomicU64::new(0),
            sent_get_frame_tree_count: AtomicU64::new(0),
            alive: Arc::new(AtomicBool::new(true)),
            alive_tx,
        });
        let browser = Arc::new(BrowserInner {
            runtime: OwnedRuntime::new(runtime),
            client: Arc::clone(&client),
            startup_probe: None,
            process: Mutex::new(None),
            profile_dir: Mutex::new(None),
            owned: false,
            ws_endpoint: "ws://test.invalid".to_string(),
            stealth_user_agent_override: Mutex::new(None),
            keyboard_platform: BrowserKeyboardPlatformState::default(),
            single_process_fallback: false,
            lifecycle: Arc::new(CloseLifecycle::new()),
            attached_pages: AttachedPageRegistry::default(),
            next_native_network_index: AtomicU64::new(1),
        });
        let page = RustwrightPage {
            inner: Arc::new(PageInner {
                browser: Arc::clone(&browser),
                target_id: "test-target".to_string(),
                registry_generation: 0,
                session_id: "test-session".to_string(),
                context_id: None,
                main_frame_id: Mutex::new(None),
                navigation_transition_lock: Mutex::new(NavigationTransitionState::default()),
                frame_state: Mutex::new(PageFrameState::new("test-session".to_string())),
                iframe_setup_tasks: IframeSetupTaskRegistry::default(),
                network_requests: Arc::new(Mutex::new(NetworkRequestStore::new(0))),
                event_stream_start_cursor: 0,
                background_override_active: Arc::new(AtomicBool::new(false)),
                screenshot_lock: Arc::new(tokio::sync::Mutex::new(())),
                mouse_dispatch_lock: Arc::new(tokio::sync::Mutex::new(())),
                fill_dispatch_lock: Arc::new(tokio::sync::Mutex::new(())),
                default_timeouts: Mutex::new(DefaultTimeoutRegister::default()),
                lifecycle: Arc::new(CloseLifecycle::new()),
                target_closed: AtomicBool::new(false),
                crashed: AtomicBool::new(false),
                close_target_on_drop: AtomicBool::new(false),
                console_records: Mutex::new(ConsoleRecordStore::default()),
                console_capture: ConsoleCaptureState::default(),
                console_replay_until_event_cursor: Mutex::new(HashMap::new()),
                observation_event_cursor: AtomicU64::new(0),
                native_network_records: Mutex::new(NativeNetworkRecordStore::new(1)),
            }),
        };
        *page.inner.main_frame_id.lock().unwrap() = Some("main-frame".to_string());
        page.inner.frame_state.lock().unwrap().record_frame(
            "main-frame".to_string(),
            None,
            None,
            None,
            "test-session".to_string(),
        );
        let token = CancelToken::new();
        let dispatch_token = token.clone();
        let responder = browser.runtime.handle().spawn(async move {
            tokio::time::timeout(Duration::from_secs(5), async move {
                let mut cancellation_won = None;
                loop {
                    let command = match write_rx.recv().await.unwrap() {
                        CdpOutgoing::Text { payload, .. } => {
                            serde_json::from_str::<Value>(&payload).unwrap()
                        }
                        CdpOutgoing::Close => panic!("unexpected transport close"),
                    };
                    let method = command["method"].as_str().unwrap();
                    let result = match method {
                        "Page.getFrameTree" => json!({
                            "frameTree": {
                                "frame": {"id": "main-frame", "url": "about:blank"}
                            }
                        }),
                        "Page.createIsolatedWorld" => json!({"executionContextId": 7}),
                        "Runtime.evaluate" => {
                            json!({
                                "result": {
                                    "type": "object",
                                    "objectId": "typing-serializer",
                                }
                            })
                        }
                        "Runtime.callFunctionOn" => {
                            json!({ "result": { "type": "boolean", "value": true } })
                        }
                        "Input.dispatchKeyEvent" => json!({}),
                        other => panic!("unexpected CDP command: {other}"),
                    };
                    let key_up =
                        method == "Input.dispatchKeyEvent" && command["params"]["type"] == "keyUp";
                    if method == "Input.dispatchKeyEvent"
                        && command["params"]["type"] == "rawKeyDown"
                        && command["params"]["key"] == "a"
                    {
                        cancellation_won = Some(dispatch_token.try_cancel());
                    }
                    dispatch_cdp_payload(
                        json!({ "id": command["id"], "result": result }),
                        Arc::clone(&pending),
                        events.clone(),
                        Arc::clone(&event_log),
                    );
                    if key_up {
                        return cancellation_won;
                    }
                }
            })
            .await
            .expect("typing responder must finish within five seconds")
        });

        let result = page.type_text_with_timeout_and_cancel(
            "#target",
            "a",
            None,
            Some(1_000.0),
            Some(&token),
        );
        let cancellation_won = browser.block_on_raw(responder).unwrap().unwrap();

        assert!(
            cancellation_won,
            "typing must remain request-cancellable while the final character is in flight"
        );
        assert!(
            result.is_ok(),
            "a fully dispatched type must not be reported as cancelled: {result:?}"
        );
        assert!(
            !token.is_physical_action_committed(),
            "typing must not claim request-level physical commitment"
        );
    }

