    #[test]
    fn written_input_timeout_becomes_unconfirmed_commitment() {
        let rejected = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Disconnected),
                write_status: TransportWriteStatus::NotWritten,
            },
            "key-down",
        );
        let error = rejected
            .result
            .expect_err("disconnect must remain a failure");
        let RwError::ActionFailure(details) = error else {
            panic!("expected classified action failure, got {error:?}");
        };
        assert!(matches!(details.cause(), RwError::Disconnected));
        assert_eq!(details.metadata().command_written, Some(CommandWritten::No));
        assert_eq!(details.metadata().retryable, Some(false));
        assert_eq!(rejected.commitment, InputActionCommitment::NotCommitted);

        let written = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Timeout(25)),
                write_status: TransportWriteStatus::Written,
            },
            "key-down",
        );
        assert!(
            written.result.is_ok(),
            "a timeout after a confirmed transport write is unconfirmed success, not a retryable failure: {:?}",
            written.result
        );
        assert_eq!(
            written.commitment,
            InputActionCommitment::WrittenUnconfirmed
        );
    }

    #[test]
    fn written_input_disconnect_and_cdp_error_stay_failures() {
        let cdp_error = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Cdp {
                    method: "Input.dispatchKeyEvent".to_string(),
                    message: "key event rejected".to_string(),
                }),
                write_status: TransportWriteStatus::Written,
            },
            "key-down",
        );
        let error = cdp_error
            .result
            .expect_err("CDP rejection must remain a failure");
        let RwError::ActionFailure(details) = error else {
            panic!("expected classified action failure, got {error:?}");
        };
        assert!(matches!(
            details.cause(),
            RwError::Cdp { method, message }
                if method == "Input.dispatchKeyEvent" && message == "key event rejected"
        ));
        assert_eq!(
            *details.metadata(),
            FailureMetadata {
                kind: None,
                phase: Some(FailurePhase::Settle),
                target_kind: Some(FailureTargetKind::Page),
                command_written: Some(CommandWritten::Yes),
                retryable: Some(true),
            }
        );
        assert_eq!(cdp_error.commitment, InputActionCommitment::NotCommitted);

        let disconnected = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Disconnected),
                write_status: TransportWriteStatus::Written,
            },
            "key-down",
        );
        let error = disconnected
            .result
            .expect_err("disconnect after write must remain a failure");
        let RwError::ActionFailure(details) = error else {
            panic!("expected classified action failure, got {error:?}");
        };
        assert!(matches!(details.cause(), RwError::Disconnected));
        assert_eq!(details.metadata().phase, Some(FailurePhase::Settle));
        assert_eq!(
            details.metadata().command_written,
            Some(CommandWritten::Yes)
        );
        assert_eq!(details.metadata().retryable, Some(false));
        assert_eq!(disconnected.commitment, InputActionCommitment::NotCommitted);
    }

    #[tokio::test]
    async fn indeterminate_input_write_surfaces_unknown_outcome() {
        let state = Arc::new(CdpWriteState::new());
        let (ack_tx, ack_rx) = oneshot::channel();
        let tracker = CdpWriteTracker {
            state: Arc::clone(&state),
            ack: ack_tx,
        };
        assert!(tracker.begin_write());
        tracker.finish(false);
        assert_eq!(
            settle_write_status(&state, ack_rx).await,
            TransportWriteStatus::Indeterminate
        );

        let resolution = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Timeout(250)),
                write_status: TransportWriteStatus::Indeterminate,
            },
            "key-down",
        );

        let error = resolution
            .result
            .expect_err("indeterminate timeout must surface unknown outcome");
        assert_eq!(
            error.to_string(),
            "input command may have reached the browser, but its outcome is unknown; retrying may repeat the action"
        );
        let RwError::ActionFailure(details) = error else {
            panic!("expected classified action failure, got {error:?}");
        };
        assert!(matches!(details.cause(), RwError::Timeout(250)));
        assert_eq!(
            *details.metadata(),
            FailureMetadata {
                kind: Some(FailureKind::UnknownOutcome),
                phase: Some(FailurePhase::Dispatch),
                target_kind: Some(FailureTargetKind::Page),
                command_written: Some(CommandWritten::Indeterminate),
                retryable: Some(false),
            }
        );
        assert!(std::error::Error::source(&details).is_none());
        assert_eq!(
            resolution.commitment,
            InputActionCommitment::WrittenUnconfirmed
        );

        let cdp_error = resolve_input_action_send(
            CdpSendOutcome {
                result: Err(RwError::Cdp {
                    method: "Input.dispatchKeyEvent".to_string(),
                    message: "key event rejected".to_string(),
                }),
                write_status: TransportWriteStatus::Indeterminate,
            },
            "key-down",
        );
        let error = cdp_error
            .result
            .expect_err("CDP rejection must remain surfaced");
        let RwError::ActionFailure(details) = error else {
            panic!("expected classified action failure, got {error:?}");
        };
        assert!(matches!(details.cause(), RwError::Cdp { .. }));
        assert_eq!(details.metadata().phase, Some(FailurePhase::Settle));
        assert_eq!(
            details.metadata().command_written,
            Some(CommandWritten::Yes)
        );
        assert_eq!(details.metadata().retryable, Some(true));
        assert_eq!(cdp_error.commitment, InputActionCommitment::NotCommitted);
    }

    fn chord_shape(key: &str) -> (Vec<String>, i64, String) {
        let chord = parse_key_chord(key, BrowserKeyboardPlatform::Control)
            .unwrap_or_else(|error| panic!("{key:?}: {error}"));
        let names = chord
            .modifiers
            .iter()
            .map(|(descriptor, _)| descriptor.key.clone())
            .collect();
        let mask = chord
            .modifiers
            .iter()
            .fold(0, |mask, (_, held)| mask | held);
        (names, mask, chord.base.key.clone())
    }

    #[test]
    fn key_chord_parsing_matches_the_dispatch_shape() {
        assert_eq!(chord_shape("a"), (Vec::new(), 0, "a".to_owned()));
        assert_eq!(
            chord_shape("Control+a"),
            (vec!["Control".to_owned()], 2, "a".to_owned())
        );
        // `+` is the chord separator, so a bare `+` has to stay addressable as a
        // base key rather than parsing as two empty parts.
        assert_eq!(
            chord_shape("+"),
            (vec!["Shift".to_owned()], 8, "+".to_owned())
        );
        assert_eq!(
            chord_shape("Control+Shift+Alt+Meta+a"),
            (
                vec![
                    "Control".to_owned(),
                    "Shift".to_owned(),
                    "Alt".to_owned(),
                    "Meta".to_owned(),
                ],
                2 | 8 | 1 | 4,
                "A".to_owned()
            )
        );
    }

    #[test]
    fn native_key_table_matches_parallel_held_state_descriptors_entry_for_entry() {
        type ExpectedDescriptor = (String, String, String, u32, u8, Option<String>, bool);
        let expected: Vec<ExpectedDescriptor> = serde_json::from_str(include_str!(
            "../tests/input_key_descriptor_conformance.json"
        ))
        .unwrap();
        for (input, key, code, virtual_key, location, text, implied_shift) in expected {
            let actual = native_key_descriptor(&input, BrowserKeyboardPlatform::Control)
                .unwrap_or_else(|error| panic!("{input:?}: {error}"));
            assert_eq!(
                (
                    actual.key,
                    actual.code,
                    actual.virtual_key,
                    actual.location,
                    actual.text,
                    actual.implied_shift,
                ),
                (key, code, virtual_key, location, text, implied_shift),
                "{input:?}"
            );
        }

        for number in 1..=12 {
            let input = format!("F{number}");
            let actual = native_key_descriptor(&input, BrowserKeyboardPlatform::Control).unwrap();
            assert_eq!(
                (actual.key, actual.code, actual.virtual_key, actual.location),
                (input.clone(), input, 111 + number, 0)
            );
            assert_eq!(actual.text, None);
            assert!(!actual.implied_shift);
        }
        for character in 'A'..='Z' {
            let input = format!("Key{character}");
            let actual = native_key_descriptor(&input, BrowserKeyboardPlatform::Control).unwrap();
            assert_eq!(actual.key, character.to_ascii_lowercase().to_string());
            assert_eq!(actual.code, input);
            assert_eq!(actual.virtual_key, u32::from(character));
            assert_eq!(actual.location, 0);
            assert_eq!(
                actual.text,
                Some(character.to_ascii_lowercase().to_string())
            );
            assert!(!actual.implied_shift);
        }
        for character in '0'..='9' {
            let input = format!("Digit{character}");
            let actual = native_key_descriptor(&input, BrowserKeyboardPlatform::Control).unwrap();
            assert_eq!(actual.key, character.to_string());
            assert_eq!(actual.code, input);
            assert_eq!(actual.virtual_key, u32::from(character));
            assert_eq!(actual.location, 0);
            assert_eq!(actual.text, Some(character.to_string()));
            assert!(!actual.implied_shift);
        }
        for character in ('a'..='z').chain('A'..='Z').chain('0'..='9') {
            let input = character.to_string();
            let actual = native_key_descriptor(&input, BrowserKeyboardPlatform::Control).unwrap();
            let expected_code = if character.is_ascii_digit() {
                format!("Digit{character}")
            } else {
                format!("Key{}", character.to_ascii_uppercase())
            };
            assert_eq!(actual.key, input);
            assert_eq!(actual.code, expected_code);
            assert_eq!(
                actual.virtual_key,
                u32::from(if character.is_ascii_digit() {
                    character
                } else {
                    character.to_ascii_uppercase()
                })
            );
            assert_eq!(actual.location, 0);
            assert_eq!(actual.text, Some(character.to_string()));
            assert!(!actual.implied_shift);
        }
    }

