    #[test]
    fn browser_keyboard_platform_state_defaults_to_control_and_sets_once() {
        let mac_first = BrowserKeyboardPlatformState::default();
        assert_eq!(mac_first.get(), BrowserKeyboardPlatform::Control);
        assert!(mac_first.set_once_from_version(&json!({
            "userAgent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 14_0)"
        })));
        assert!(!mac_first.set_once_from_version(&json!({
            "userAgent": "Mozilla/5.0 (X11; Linux x86_64)"
        })));
        assert_eq!(mac_first.get(), BrowserKeyboardPlatform::Mac);

        let control_first = BrowserKeyboardPlatformState::default();
        assert!(control_first.set_once_from_version(&json!({
            "userAgent": "Mozilla/5.0 (X11; Linux x86_64)"
        })));
        assert!(!control_first.set_once_from_version(&json!({
            "userAgent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 14_0)"
        })));
        assert_eq!(control_first.get(), BrowserKeyboardPlatform::Control);
    }

    #[test]
    fn key_chord_parsing_deduplicates_repeated_modifiers() {
        // Holding a held modifier is a no-op for the page but not for us: each
        // repeat costs another key-down dispatch and another key-up that must be
        // cleaned up under its own budget after the press commits. Without the
        // dedup, a caller-supplied string scales that work linearly.
        let (names, mask, base) = chord_shape("Control+Control+Control+Shift+Shift+a");
        assert_eq!(names, vec!["Control".to_owned(), "Shift".to_owned()]);
        assert_eq!(base, "A");
        // The mask a repeated modifier produces is the mask it produces once, so
        // deduplicating cannot change what the page sees.
        assert_eq!(mask, chord_shape("Control+Shift+a").1);
        // `Control` and `ControlLeft` are the same physical key, so the second
        // one is the redundant repeat the dedup is for.
        assert_eq!(chord_shape("ControlLeft+Control+a").0.len(), 1);

        // Left and right modifiers share a mask but are different keys: a page
        // reading `event.code` can tell them apart, so both key-downs still go
        // out. Deduplicating by mask instead of by code would silently drop one.
        let paired = parse_key_chord(
            "ControlLeft+ControlRight+a",
            BrowserKeyboardPlatform::Control,
        )
        .expect("paired chord");
        assert_eq!(
            paired
                .modifiers
                .iter()
                .map(|(descriptor, _)| descriptor.code.as_str())
                .collect::<Vec<_>>(),
            vec!["ControlLeft", "ControlRight"]
        );
    }

    #[test]
    fn key_chord_parsing_rejects_unusable_keys_before_any_dispatch() {
        // Every one of these used to be discovered after the caller's target had
        // already been focused -- and, for a bad base key behind a good modifier,
        // after that modifier's key-down had already been dispatched.
        for key in ["", "Control+", "+a", "a++b"] {
            assert!(
                matches!(
                    parse_key_chord(key, BrowserKeyboardPlatform::Control),
                    Err(RwError::InvalidInput(message)) if message.starts_with("unsupported key:")
                ),
                "{key:?} should be rejected as an empty chord part"
            );
        }
        assert!(matches!(
            parse_key_chord("Hyper+a", BrowserKeyboardPlatform::Control),
            Err(RwError::InvalidInput(message)) if message == "unsupported key modifier: Hyper"
        ));
        assert!(
            parse_key_chord("Control+NoSuchKey", BrowserKeyboardPlatform::Control).is_err(),
            "an unknown base key must fail before its modifier is pressed"
        );
    }

    #[test]
    fn locator_wait_context_loss_classification_is_narrow() {
        for message in [
            "Inspected target navigated or closed",
            "Execution context was destroyed.",
            "Cannot find context with specified id",
            "Session with given id not found.",
            "CDP session is detached",
            "No frame for given id found",
        ] {
            assert!(is_locator_wait_context_loss(&RwError::Cdp {
                method: "Runtime.evaluate".to_string(),
                message: message.to_string(),
            }));
        }

        for message in [
            "Target closed",
            "Session closed",
            "CDP websocket is closed",
            "Invalid selector",
        ] {
            assert!(!is_locator_wait_context_loss(&RwError::Cdp {
                method: "Runtime.evaluate".to_string(),
                message: message.to_string(),
            }));
        }
        assert!(!is_locator_wait_context_loss(&RwError::Message(
            "Execution context was destroyed.".to_string()
        )));
        assert!(!is_locator_wait_context_loss(&RwError::Timeout(100)));
    }

    #[test]
    fn actionability_terminal_states_have_distinct_errors() {
        let actionable = ActionabilityState {
            count: 1,
            strict_violation: false,
            attached: true,
            visible: true,
            enabled: true,
            stable: true,
            receives_events: true,
            point_x: None,
            point_y: None,
            rect_x: None,
            rect_y: None,
        };
        let cases = [
            (
                ActionabilityState {
                    attached: false,
                    ..actionable
                },
                ActionabilityError::Detached,
            ),
            (
                ActionabilityState {
                    visible: false,
                    ..actionable
                },
                ActionabilityError::NotVisible,
            ),
            (
                ActionabilityState {
                    enabled: false,
                    ..actionable
                },
                ActionabilityError::Disabled,
            ),
            (
                ActionabilityState {
                    stable: false,
                    ..actionable
                },
                ActionabilityError::NotStable,
            ),
            (
                ActionabilityState {
                    receives_events: false,
                    ..actionable
                },
                ActionabilityError::NotReceivingEvents,
            ),
        ];

        for (state, expected) in cases {
            assert!(matches!(
                terminal_actionability_error(Some(&state), Duration::from_millis(10), true),
                RwError::Actionability(actual) if actual == expected
            ));
        }
        assert!(matches!(
            terminal_actionability_error(None, Duration::from_millis(10), true),
            RwError::Timeout(10)
        ));
        assert!(matches!(
            terminal_actionability_error(
                Some(&ActionabilityState {
                    enabled: false,
                    ..actionable
                }),
                Duration::from_millis(10),
                false,
            ),
            RwError::Timeout(10)
        ));
    }

    #[test]
    fn hit_tested_point_translation_preserves_clamping_and_frame_offsets() {
        let partially_offscreen = HitTestedLocatorPoint {
            point: ActionabilityPoint { x: 0.0, y: 142.0 },
            rect: ActionabilityRect {
                x: -1000.0,
                y: 120.0,
            },
        };
        assert_eq!(
            translate_hit_tested_point(-1000.0, 120.0, partially_offscreen),
            (0.0, 142.0)
        );

        let same_process_frame = HitTestedLocatorPoint {
            point: ActionabilityPoint { x: 190.0, y: 104.0 },
            rect: ActionabilityRect { x: 110.0, y: 80.0 },
        };
        assert_eq!(
            translate_hit_tested_point(250.0, 170.0, same_process_frame),
            (330.0, 194.0)
        );

        assert_eq!(
            translate_hit_tested_point(110.0, 80.0, same_process_frame),
            (190.0, 104.0)
        );
    }

    #[test]
    fn cached_main_frame_url_prefers_last_navigated_url() {
        let mut state = PageFrameState::new("session-main".to_string());

        // No main frame known yet -> caller must fall back to the live probe.
        assert_eq!(resolve_cached_main_frame_url(None, &state), None);

        // Frame attached but no committed url yet -> still fall back.
        state.record_frame(
            "MAIN".to_string(),
            None,
            None,
            None,
            "session-main".to_string(),
        );
        assert_eq!(resolve_cached_main_frame_url(Some("MAIN"), &state), None);

        // After Page.frameNavigated the cached url is served with no round-trip.
        state.record_frame(
            "MAIN".to_string(),
            None,
            None,
            Some("https://example.com/".to_string()),
            "session-main".to_string(),
        );
        assert_eq!(
            resolve_cached_main_frame_url(Some("MAIN"), &state),
            Some("https://example.com/".to_string()),
        );

        // A subsequent navigation updates the cached value (Playwright parity).
        state.record_frame(
            "MAIN".to_string(),
            None,
            None,
            Some("https://example.com/submit".to_string()),
            "session-main".to_string(),
        );
        assert_eq!(
            resolve_cached_main_frame_url(Some("MAIN"), &state),
            Some("https://example.com/submit".to_string()),
        );
    }

    #[test]
    fn nested_oopif_attachment_preserves_parent_session_root() {
        let mut state = PageFrameState::new("session-main".to_string());
        state.record_frame(
            "main".to_string(),
            None,
            None,
            None,
            "session-main".to_string(),
        );
        state.record_session_for_frame("outer", "session-outer");
        state.record_frame(
            "outer".to_string(),
            Some("main".to_string()),
            None,
            None,
            "session-outer".to_string(),
        );

        state.record_frame(
            "inner".to_string(),
            Some("outer".to_string()),
            None,
            None,
            "session-outer".to_string(),
        );
        assert_eq!(
            state
                .session_frames
                .get("session-outer")
                .map(String::as_str),
            Some("outer")
        );
        assert_eq!(
            state.frame_sessions.get("inner").map(String::as_str),
            Some("session-outer")
        );
        assert!(state.frames.contains_key("outer"));

        state.record_session_for_frame("inner", "session-inner");
        assert_eq!(
            state
                .session_frames
                .get("session-outer")
                .map(String::as_str),
            Some("outer")
        );
        assert_eq!(
            state
                .session_frames
                .get("session-inner")
                .map(String::as_str),
            Some("inner")
        );
        assert_eq!(state.frames["inner"].parent_id.as_deref(), Some("outer"));

        state.record_frame(
            "leaf".to_string(),
            Some("inner".to_string()),
            None,
            None,
            "session-inner".to_string(),
        );
        state.detach_session("session-inner");
        assert!(!state.session_frames.contains_key("session-inner"));
        assert_eq!(
            state.frame_sessions.get("inner").map(String::as_str),
            Some("session-outer")
        );
        assert_eq!(
            state.frame_sessions.get("leaf").map(String::as_str),
            Some("session-outer")
        );
        assert_eq!(
            state.frames["inner"].session_id.as_deref(),
            Some("session-outer")
        );
        assert_eq!(
            state.frames["leaf"].session_id.as_deref(),
            Some("session-outer")
        );
        assert_eq!(
            state
                .session_frames
                .get("session-outer")
                .map(String::as_str),
            Some("outer")
        );
    }

