    #[test]
    fn native_locator_probe_builders_replace_all_placeholders() {
        let probe = locator_probe_state_body(
            r#"{"scroll":true,"stable":true,"receives_events":true,"stable_position_required":false,"action_position":{"x":4.5,"y":9}}"#,
        )
        .unwrap();
        for placeholder in [
            "__SCROLL__",
            "__STABLE__",
            "__RECEIVES_EVENTS__",
            "__STABLE_POSITION_REQUIRED__",
            "__ACTION_POSITION__",
        ] {
            assert!(!probe.contains(placeholder));
        }
        assert!(probe.contains("const actionPosition = {\"x\":4.5,\"y\":9.0};"));

        let fill = locator_fill_apply_body("Ada", true, false).unwrap();
        for placeholder in ["__STRICT__", "__FORCED__", "__VALUE__"] {
            assert!(!fill.body.contains(placeholder));
        }
        assert!(fill.body.contains("let value = \"Ada\";"));
        assert!(fill.body.contains("'hidden'"));
        assert!(fill.body.contains("value = value.trim();"));
        assert!(fill.body.contains("value = value.toLowerCase();"));
        assert!(fill.body.contains("composed: true"));
        assert!(fill.body.contains("expiresAt: guardDeadline"));
        assert!(!fill.body.contains("valueLikeApplied"));
        assert!(fill.body.contains("__RUSTWRIGHT_FILL_DISPATCH_ID__"));
        assert!(fill.body.contains("__RUSTWRIGHT_FILL_DISPATCH_TOKEN__"));
        let value_like_mutation = fill.body.find("valueSetter.call(el, value);").unwrap();
        let value_like_receipt = fill.body.find("binding(JSON.stringify({").unwrap();
        let value_like_event = fill
            .body
            .find("el.dispatchEvent(new Event('input'")
            .unwrap();
        assert!(value_like_mutation < value_like_receipt);
        assert!(value_like_receipt < value_like_event);
        assert!(fill
            .body
            .contains(&format!("const fillGuardKey = {:?};", fill.guard_key)));

        let select = locator_select_apply_script(r#"["a"]"#, "[]", "[1]").unwrap();
        for placeholder in ["__VALUES__", "__LABELS__", "__INDEXES__"] {
            assert!(!select.prepare_body.contains(placeholder));
        }
        assert!(select.prepare_body.contains(r#"const values = ["a"];"#));
        assert!(select.prepare_body.contains("const indexes = [1];"));
        assert!(select.dispatch_body.contains("el.dispatchEvent"));
    }

    #[test]
    fn shadow_query_helper_uses_lexer_ast_and_iterative_traversal() {
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const isCssWhitespace = char =>"));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const cssTrim = text =>"));
        for code_point in [
            r#"'\u0009'"#,
            r#"'\u000a'"#,
            r#"'\u000c'"#,
            r#"'\u000d'"#,
            r#"'\u0020'"#,
        ] {
            assert!(SHADOW_PIERCING_QUERY_HELPER.contains(code_point));
        }
        assert!(!SHADOW_PIERCING_QUERY_HELPER.contains(r#"/\s/"#));
        assert!(!SHADOW_PIERCING_QUERY_HELPER.contains(".trim()"));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const lex = text =>"));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const parseSelectorList ="));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const matchesComplex ="));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("const matchesRelative ="));
        assert!(SHADOW_PIERCING_QUERY_HELPER.contains("while (stack.length)"));
        assert!(!SHADOW_PIERCING_QUERY_HELPER.contains("const visit ="));
        assert!(!SHADOW_PIERCING_QUERY_HELPER.contains("Unsupported shadow-piercing"));
    }

