    #[test]
    fn public_click_delivers_dialog_then_accepts_or_dismisses_to_completion() {
        for accept in [true, false] {
            let mut harness = navigation_test_harness(32);
            let page = RustwrightPage {
                inner: Arc::clone(&harness.page),
            };
            let events = page.events();
            let (dialog_command_tx, dialog_command_rx) = std::sync::mpsc::channel();
            let (responder_done_tx, responder_done_rx) = std::sync::mpsc::channel();
            let handle = harness.page.browser.runtime.handle().clone();
            handle.spawn(async move {
                harness
                    .reply_next(
                        "Page.navigate",
                        json!({ "frameId": "frame-main", "loaderId": "loader-main" }),
                    )
                    .await;
                harness.emit(json!({
                    "sessionId": "page-session",
                    "method": "Page.loadEventFired",
                    "params": {}
                }));
                harness
                    .reply_next(
                        "Page.getFrameTree",
                        json!({ "frameTree": { "frame": { "id": "frame-main", "url": "https://example.test/dialog" } } }),
                    )
                    .await;
                let utility_world = harness.next_command("Page.createIsolatedWorld").await;
                assert_eq!(
                    utility_world.pointer("/params/frameId").and_then(Value::as_str),
                    Some("frame-main")
                );
                harness.reply(&utility_world, json!({ "executionContextId": 1 }));
                harness
                    .reply_next(
                        "Runtime.evaluate",
                        json!({
                            "result": {
                                "type": "object",
                                "objectId": "dialog-action-serializer",
                            }
                        }),
                    )
                    .await;
                harness
                    .reply_next(
                        "Runtime.callFunctionOn",
                        json!({
                            "result": {
                                "type": "object",
                                "value": {
                                    "count": 1,
                                    "strict_violation": false,
                                    "attached": true,
                                    "visible": true,
                                    "enabled": true,
                                    "stable": true,
                                    "receives_events": true,
                                    "point_x": 5.0,
                                    "point_y": 6.0,
                                    "rect_x": 0.0,
                                    "rect_y": 0.0
                                }
                            }
                        }),
                    )
                    .await;
                harness
                    .reply_next(
                        "Page.getFrameTree",
                        json!({ "frameTree": { "frame": { "id": "frame-main", "url": "https://example.test/dialog" } } }),
                    )
                    .await;
                let utility_world = harness.next_command("Page.createIsolatedWorld").await;
                assert_eq!(
                    utility_world.pointer("/params/frameId").and_then(Value::as_str),
                    Some("frame-main")
                );
                harness.reply(&utility_world, json!({ "executionContextId": 2 }));
                harness
                    .reply_next_runtime_evaluation(
                        json!({ "result": { "type": "object", "objectId": "node-dialog" } }),
                    )
                    .await;
                harness
                    .reply_next(
                        "DOM.getBoxModel",
                        json!({ "model": { "border": [0, 0, 10, 0, 10, 12, 0, 12] } }),
                    )
                    .await;
                harness.reply_next("Runtime.releaseObject", json!({})).await;
                let mut ordering_barrier = None;
                let mut dialog_handled = false;
                let mut mouse_released = false;
                while !mouse_released || !dialog_handled || ordering_barrier.is_none() {
                    let command = harness.next_command_any().await;
                    match command["method"].as_str() {
                        Some("Input.dispatchMouseEvent") => {
                            let event_type = command.pointer("/params/type").and_then(Value::as_str);
                            assert!(
                                harness.events.receiver_count() >= 2,
                                "public dialog and settlement receivers must exist before click dispatch"
                            );
                            if event_type == Some("mousePressed") {
                                harness.emit(json!({
                                    "sessionId": "page-session",
                                    "method": "Page.javascriptDialogOpening",
                                    "params": { "type": "confirm", "message": "continue?" }
                                }));
                            }
                            harness.reply(&command, json!({}));
                            if event_type == Some("mouseReleased") {
                                assert!(!mouse_released, "mouseReleased must be sent exactly once");
                                mouse_released = true;
                            }
                        }
                        Some("Runtime.evaluate") => {
                            assert!(ordering_barrier.is_none(), "duplicate ordering barrier");
                            ordering_barrier = Some(command);
                        }
                        Some("Page.handleJavaScriptDialog") => {
                            assert!(!dialog_handled, "dialog must be handled exactly once");
                            assert_eq!(command["params"]["accept"], accept);
                            harness.reply(&command, json!({}));
                            dialog_command_tx.send(()).unwrap();
                            dialog_handled = true;
                        }
                        method => {
                            panic!("unexpected command while click or dialog is pending: {method:?}")
                        }
                    }
                }
                let barrier = ordering_barrier.expect("pointer ordering barrier");
                harness.reply(
                    &barrier,
                    json!({ "result": { "type": "undefined" } }),
                );
                responder_done_tx.send(()).unwrap();
            });

            page.goto(
                "https://example.test/dialog",
                Some("load"),
                Some(1_000.0),
                None,
            )
            .expect("public goto prerequisite");
            let (click_tx, click_rx) = std::sync::mpsc::channel();
            let click_page = page.clone();
            let click = std::thread::spawn(move || {
                click_tx
                    .send(click_page.click("#dialog", Some(1_000.0)))
                    .unwrap();
            });
            let RustwrightPageEvent::Dialog { dialog, .. } = events
                .recv_timeout(Duration::from_secs(1))
                .expect("public click must deliver its dialog")
            else {
                panic!("expected dialog event")
            };
            assert!(
                matches!(
                    click_rx.try_recv(),
                    Err(std::sync::mpsc::TryRecvError::Empty)
                ),
                "click must remain pending until the dialog is resolved"
            );
            if accept {
                dialog.accept(None).unwrap();
            } else {
                dialog.dismiss().unwrap();
            }
            dialog_command_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("dialog command must complete");
            click_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("click completion must arrive")
                .expect("public click should complete");
            responder_done_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("CDP responder must complete");
            click.join().expect("join public click");
        }
    }

    #[derive(Clone, Copy)]
    enum PublicSettledAction {
        Scroll,
        Hover,
        Check,
    }

    fn run_public_settled_action(action: PublicSettledAction) {
        let mut harness = navigation_test_harness(32);
        let page = RustwrightPage {
            inner: Arc::clone(&harness.page),
        };
        let handle = harness.page.browser.runtime.handle().clone();
        handle.spawn(async move {
            harness
                .reply_next(
                    "Page.navigate",
                    json!({ "frameId": "frame-main", "loaderId": "loader-main" }),
                )
                .await;
            harness.emit(json!({
                "sessionId": "page-session",
                "method": "Page.loadEventFired",
                "params": {}
            }));
            harness
                .reply_next(
                    "Page.getFrameTree",
                    json!({ "frameTree": { "frame": { "id": "frame-main", "url": "https://example.test/action" } } }),
                )
                .await;

            let utility_world = harness.next_command("Page.createIsolatedWorld").await;
            assert_eq!(
                utility_world.pointer("/params/frameId").and_then(Value::as_str),
                Some("frame-main")
            );
            harness.reply(&utility_world, json!({ "executionContextId": 1 }));
            harness
                .reply_next(
                    "Runtime.evaluate",
                    json!({
                        "result": {
                            "type": "object",
                            "objectId": "public-action-serializer",
                        }
                    }),
                )
                .await;

            if matches!(action, PublicSettledAction::Scroll) {
                let dispatch = harness.next_command("Runtime.callFunctionOn").await;
                assert!(
                    harness.events.receiver_count() >= 1,
                    "scroll settlement must subscribe before its dispatch"
                );
                harness.reply(
                    &dispatch,
                    json!({ "result": { "type": "boolean", "value": true } }),
                );
                harness
                    .reply_next(
                        "Runtime.evaluate",
                        json!({ "result": { "type": "undefined" } }),
                    )
                    .await;
                return;
            }

            harness
                .reply_next(
                    "Runtime.callFunctionOn",
                    json!({
                        "result": {
                            "type": "object",
                            "value": {
                                "count": 1,
                                "strict_violation": false,
                                "attached": true,
                                "visible": true,
                                "enabled": true,
                                "stable": true,
                                "receives_events": true,
                                "point_x": 5.0,
                                "point_y": 6.0,
                                "rect_x": 0.0,
                                "rect_y": 0.0
                            }
                        }
                    }),
                )
                .await;
            harness
                .reply_next(
                    "Page.getFrameTree",
                    json!({ "frameTree": { "frame": { "id": "frame-main", "url": "https://example.test/action" } } }),
                )
                .await;
            let utility_world = harness.next_command("Page.createIsolatedWorld").await;
            assert_eq!(
                utility_world.pointer("/params/frameId").and_then(Value::as_str),
                Some("frame-main")
            );
            harness.reply(&utility_world, json!({ "executionContextId": 2 }));
            harness
                .reply_next_runtime_evaluation(
                    json!({ "result": { "type": "object", "objectId": "node-1" } }),
                )
                .await;
            harness
                .reply_next(
                    "DOM.getBoxModel",
                    json!({ "model": { "border": [0, 0, 10, 0, 10, 12, 0, 12] } }),
                )
                .await;
            harness.reply_next("Runtime.releaseObject", json!({})).await;

            if matches!(action, PublicSettledAction::Check) {
                let utility_world = harness.next_command("Page.createIsolatedWorld").await;
                assert_eq!(
                    utility_world.pointer("/params/frameId").and_then(Value::as_str),
                    Some("frame-main")
                );
                harness.reply(&utility_world, json!({ "executionContextId": 3 }));
                harness
                    .reply_next(
                        "Runtime.callFunctionOn",
                        json!({
                            "result": {
                                "type": "string",
                                "value": "{\"valid\":true,\"checked\":false,\"native_radio\":false}"
                            }
                        }),
                    )
                    .await;
            }

            loop {
                let command = harness.next_command_any().await;
                let method = command["method"].as_str().unwrap();
                if method == "Input.dispatchMouseEvent" {
                    assert!(
                        harness.events.receiver_count() >= 1,
                        "pointer settlement must subscribe before input dispatch"
                    );
                    let event_type = command.pointer("/params/type").and_then(Value::as_str);
                    harness.reply(&command, json!({}));
                    if matches!(action, PublicSettledAction::Hover)
                        || event_type == Some("mouseReleased")
                    {
                        break;
                    }
                } else {
                    panic!("unexpected action command: {command}");
                }
            }
            harness
                .reply_next(
                    "Runtime.evaluate",
                    json!({ "result": { "type": "undefined" } }),
                )
                .await;
            if matches!(action, PublicSettledAction::Check) {
                let utility_world = harness.next_command("Page.createIsolatedWorld").await;
                assert_eq!(
                    utility_world.pointer("/params/frameId").and_then(Value::as_str),
                    Some("frame-main")
                );
                harness.reply(&utility_world, json!({ "executionContextId": 4 }));
                harness
                    .reply_next(
                        "Runtime.callFunctionOn",
                        json!({ "result": { "type": "boolean", "value": true } }),
                    )
                    .await;
            }
        });

        page.goto(
            "https://example.test/action",
            Some("load"),
            Some(1_000.0),
            None,
        )
        .expect("public goto prerequisite");
        match action {
            PublicSettledAction::Scroll => page.scroll_into_view("#target"),
            PublicSettledAction::Hover => page.hover("#target"),
            PublicSettledAction::Check => page.check("#target"),
        }
        .expect("public settled action");
    }

    #[test]
    fn public_goto_then_scroll_hover_and_check_subscribe_before_dispatch() {
        for action in [
            PublicSettledAction::Scroll,
            PublicSettledAction::Hover,
            PublicSettledAction::Check,
        ] {
            run_public_settled_action(action);
        }
    }

    #[tokio::test]
    async fn evaluate_data_result_is_one_runtime_command_and_handle_path_is_unchanged() {
        let mut harness = navigation_test_harness(4);

        let client = Arc::clone(&harness.page.browser.client);
        let warmup = tokio::spawn(async move {
            evaluate_expression_in_session_before(
                &client,
                "page-session",
                None,
                make_evaluate_expression("0", None),
                OperationDeadline::new(Duration::from_secs(1)),
            )
            .await
        });
        let install_command = harness.next_command("Runtime.evaluate").await;
        assert_eq!(install_command["params"]["returnByValue"], false);
        assert_eq!(
            install_command["params"]["expression"],
            format!("({})()", runtime_value_serializer_factory())
        );
        harness.reply(
            &install_command,
            json!({
                "result": {
                    "type": "function",
                    "objectId": "serializer-main",
                },
            }),
        );
        let warmup_command = harness.next_command("Runtime.callFunctionOn").await;
        assert_eq!(warmup_command["params"]["objectId"], "serializer-main");
        assert_eq!(
            warmup_command["params"]["arguments"],
            json!([{ "objectId": "serializer-main" }])
        );
        harness.reply(
            &warmup_command,
            json!({ "result": { "type": "number", "value": 0 } }),
        );
        assert_eq!(warmup.await.unwrap().unwrap(), "0");

        let client = Arc::clone(&harness.page.browser.client);
        let object_evaluate = tokio::spawn(async move {
            evaluate_expression_in_session_before(
                &client,
                "page-session",
                None,
                "({ answer: 42 })".to_string(),
                OperationDeadline::new(Duration::from_secs(1)),
            )
            .await
        });
        let object_command = harness.next_command("Runtime.callFunctionOn").await;
        assert_eq!(object_command["params"]["objectId"], "serializer-main");
        assert_eq!(object_command["params"]["returnByValue"], true);
        assert_eq!(
            object_command["params"]["arguments"],
            json!([{ "objectId": "serializer-main" }])
        );
        assert_eq!(
            object_command["params"]["functionDeclaration"],
            serialize_evaluate_result_function("({ answer: 42 })")
        );
        assert!(object_command["params"]["functionDeclaration"]
            .as_str()
            .unwrap()
            .contains("__rustwright_evaluate_wrapper__"));
        assert!(!object_command["params"]["functionDeclaration"]
            .as_str()
            .unwrap()
            .contains(RUNTIME_VALUE_SERIALIZER));
        harness.reply(
            &object_command,
            json!({
                "result": {
                    "type": "object",
                    "value": {
                        "__rustwright_cdp_object__": 1,
                        "entries": { "answer": 42 },
                    },
                },
            }),
        );
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(1), object_evaluate)
                .await
                .expect("steady object evaluate should finish after one Runtime reply")
                .unwrap()
                .unwrap(),
            json!({
                "__rustwright_cdp_object__": 1,
                "entries": { "answer": 42 },
            })
            .to_string()
        );
        assert!(matches!(
            harness.write_rx.try_recv(),
            Err(tokio::sync::mpsc::error::TryRecvError::Empty)
        ));

        let client = Arc::clone(&harness.page.browser.client);
        let primitive_evaluate = tokio::spawn(async move {
            evaluate_expression_in_session_before(
                &client,
                "page-session",
                None,
                make_evaluate_expression("1", None),
                OperationDeadline::new(Duration::from_secs(1)),
            )
            .await
        });
        let primitive_command = harness.next_command("Runtime.callFunctionOn").await;
        assert_eq!(primitive_command["params"]["objectId"], "serializer-main");
        assert_eq!(
            primitive_command["params"]["arguments"],
            json!([{ "objectId": "serializer-main" }])
        );
        harness.reply(
            &primitive_command,
            json!({ "result": { "type": "number", "value": 1 } }),
        );
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(1), primitive_evaluate)
                .await
                .expect("primitive evaluate should keep its one-command path")
                .unwrap()
                .unwrap(),
            "1"
        );
        assert!(matches!(
            harness.write_rx.try_recv(),
            Err(tokio::sync::mpsc::error::TryRecvError::Empty)
        ));

        let page = Arc::clone(&harness.page);
        let call_function_evaluate = tokio::spawn(async move {
            evaluate_locator_for_element_handle(
                page,
                "element-handle-1".to_string(),
                Some("page-session".to_string()),
                r##"{"kind":"css","selector":"#target"}"##.to_string(),
                0,
                "return { answer: 42 };".to_string(),
                Duration::from_secs(1),
                true,
                false,
                Duration::ZERO,
            )
            .await
        });
        let call_function_command = harness.next_command("Runtime.callFunctionOn").await;
        assert_eq!(
            call_function_command["params"]["objectId"],
            "element-handle-1"
        );
        assert_eq!(
            call_function_command["params"]["arguments"],
            json!([{ "objectId": "serializer-main" }])
        );
        assert!(call_function_command["params"]["functionDeclaration"]
            .as_str()
            .unwrap()
            .contains("__rustwright_evaluate_wrapper__"));
        assert!(!call_function_command["params"]["functionDeclaration"]
            .as_str()
            .unwrap()
            .contains(RUNTIME_VALUE_SERIALIZER));
        harness.reply(
            &call_function_command,
            json!({
                "result": {
                    "type": "object",
                    "value": {
                        "__rustwright_cdp_object__": 1,
                        "entries": { "answer": 42 },
                    },
                },
            }),
        );
        assert_eq!(
            call_function_evaluate.await.unwrap().unwrap(),
            json!({
                "__rustwright_cdp_object__": 1,
                "entries": { "answer": 42 },
            })
            .to_string()
        );

        let client = Arc::clone(&harness.page.browser.client);
        let handle_evaluate = tokio::spawn(async move {
            evaluate_handle_expression_in_session(
                &client,
                "page-session",
                "globalThis".to_string(),
                OperationDeadline::new(Duration::from_secs(1)),
            )
            .await
        });
        let handle_command = harness.next_command("Runtime.evaluate").await;
        assert_eq!(handle_command["params"]["returnByValue"], false);
        assert_eq!(handle_command["params"]["expression"], "globalThis");
        harness.reply(
            &handle_command,
            json!({ "result": { "type": "object", "objectId": "remote-handle-1" } }),
        );
        assert_eq!(
            handle_evaluate.await.unwrap().unwrap(),
            json!({ "type": "object", "objectId": "remote-handle-1" })
        );
        assert!(matches!(
            harness.write_rx.try_recv(),
            Err(tokio::sync::mpsc::error::TryRecvError::Empty)
        ));
    }

