async fn create_target_cancellation_safe(
    browser: Arc<BrowserInner>,
    params: Value,
) -> RwResult<CreatedTargetGuard> {
    let task_browser = Arc::clone(&browser);
    tokio::spawn(async move {
        let target = task_browser
            .client
            .send("Target.createTarget", params, None, Duration::from_secs(10))
            .await?;
        let target_id = target
            .get("targetId")
            .and_then(Value::as_str)
            .ok_or_else(|| RwError::Message("CDP did not return a targetId".to_string()))?
            .to_string();
        Ok(CreatedTargetGuard::new(task_browser, target_id))
    })
    .await
    .map_err(|error| RwError::Message(error.to_string()))?
}

impl Drop for CreatedTargetGuard {
    fn drop(&mut self) {
        let Some(target_id) = self.target_id.take() else {
            return;
        };
        let browser = Arc::clone(&self.browser);
        let runtime = browser.runtime.handle().clone();
        runtime.spawn(async move {
            let _ = browser
                .client
                .send(
                    "Target.closeTarget",
                    json!({ "targetId": target_id }),
                    None,
                    Duration::from_secs(5),
                )
                .await;
        });
    }
}

impl PageInner {
    fn mark_delivered(&self) {
        self.close_target_on_drop.store(false, Ordering::SeqCst);
    }

    fn abort_iframe_setup_tasks(&self) {
        self.iframe_setup_tasks.abort_all();
    }

    fn close_in_background(&self) {
        self.abort_iframe_setup_tasks();
        if !self.close_target_on_drop.swap(false, Ordering::SeqCst)
            || self.lifecycle.is_closing_or_closed()
        {
            return;
        }
        let browser = Arc::clone(&self.browser);
        let target_id = self.target_id.clone();
        let lifecycle = Arc::clone(&self.lifecycle);
        let runtime = browser.runtime.handle().clone();
        runtime.spawn(async move {
            let _ = single_flight_close(lifecycle, false, move || async move {
                browser
                    .client
                    .send(
                        "Target.closeTarget",
                        json!({ "targetId": target_id }),
                        None,
                        Duration::from_secs(5),
                    )
                    .await
                    .map(|_| ())
            })
            .await;
        });
    }
}

impl Drop for PageInner {
    fn drop(&mut self) {
        self.abort_iframe_setup_tasks();
        self.browser.attached_pages.remove_page(
            &self.target_id,
            self.registry_generation,
            self as *const PageInner,
        );
        self.close_in_background();
    }
}

#[derive(Clone)]
struct NetworkRequestStore {
    requests: HashMap<String, NetworkRequestEntry>,
    next_applied_seq: u64,
    applied_order: VecDeque<(u64, String)>,
    reset_clock: Arc<AtomicU64>,
    reset_generation: u64,
    reset_cursor: u64,
}

#[derive(Clone)]
struct NetworkRequestSnapshot {
    seq: u64,
    request: Value,
    redirect_ancestry: Vec<u64>,
}

impl NetworkRequestSnapshot {
    fn clone_pruning_redirects_before(&self, reset_cursor: u64) -> Self {
        let mut snapshot = self.clone();
        let mut current = &mut snapshot.request;
        let mut retained_ancestors = 0;
        for ancestor_seq in &self.redirect_ancestry {
            if *ancestor_seq < reset_cursor {
                current.as_object_mut().unwrap().remove("redirected_from");
                snapshot.redirect_ancestry.truncate(retained_ancestors);
                return snapshot;
            }
            let Some(redirected_from) = current.get_mut("redirected_from") else {
                snapshot.redirect_ancestry.truncate(retained_ancestors);
                return snapshot;
            };
            current = redirected_from;
            retained_ancestors += 1;
        }
        if current.get("redirected_from").is_some() {
            current.as_object_mut().unwrap().remove("redirected_from");
        }
        snapshot
    }
}

impl NetworkRequestStore {
    fn new(next_applied_seq: u64) -> Self {
        Self {
            requests: HashMap::new(),
            next_applied_seq,
            applied_order: VecDeque::new(),
            reset_clock: Arc::new(AtomicU64::new(0)),
            reset_generation: 0,
            reset_cursor: next_applied_seq,
        }
    }

    fn reset_after_overflow(&mut self, next_applied_seq: u64) {
        self.requests.clear();
        self.next_applied_seq = next_applied_seq;
        self.applied_order.clear();
        self.reset_generation = self.reset_clock.fetch_add(1, Ordering::SeqCst) + 1;
        self.reset_cursor = next_applied_seq;
    }

    fn record_applied_request(&mut self, seq: u64, request_id: String) {
        self.applied_order.push_back((seq, request_id));
        while self.applied_order.len() > CDP_EVENT_LOG_LIMIT {
            let Some((oldest_seq, oldest_request_id)) = self.applied_order.pop_front() else {
                break;
            };
            if let Some(entry) = self.requests.get_mut(&oldest_request_id) {
                entry.applied_by_seq.remove(&oldest_seq);
            }
        }
    }

    fn merge_committed(&mut self, committed: &Self) {
        if committed.reset_generation > self.reset_generation {
            let reset_cursor = committed.reset_cursor;
            self.applied_order.retain(|(seq, _)| *seq >= reset_cursor);
            self.requests.retain(|_, entry| {
                entry.applied_by_seq.retain(|seq, _| *seq >= reset_cursor);
                for snapshot in entry.applied_by_seq.values_mut() {
                    *snapshot = snapshot.clone_pruning_redirects_before(reset_cursor);
                }
                if let Some((_, newest)) = entry.applied_by_seq.last_key_value() {
                    entry.current = newest.clone();
                    true
                } else {
                    false
                }
            });
            self.reset_generation = committed.reset_generation;
            self.reset_cursor = reset_cursor;
        }
        let reset_cursor = self.reset_cursor;
        let committed_predates_reset = committed.reset_generation < self.reset_generation;
        for (request_id, committed_entry) in &committed.requests {
            let mut committed_mutations = committed_entry.applied_by_seq.range(reset_cursor..);
            let Some((first_seq, first_snapshot)) = committed_mutations.next() else {
                continue;
            };
            let first_snapshot = if committed_predates_reset {
                first_snapshot.clone_pruning_redirects_before(reset_cursor)
            } else {
                first_snapshot.clone()
            };
            let live_entry =
                self.requests
                    .entry(request_id.clone())
                    .or_insert_with(|| NetworkRequestEntry {
                        current: first_snapshot.clone(),
                        applied_by_seq: BTreeMap::new(),
                    });
            live_entry
                .applied_by_seq
                .entry(*first_seq)
                .or_insert(first_snapshot);
            for (seq, snapshot) in committed_mutations {
                let snapshot = if committed_predates_reset {
                    snapshot.clone_pruning_redirects_before(reset_cursor)
                } else {
                    snapshot.clone()
                };
                live_entry.applied_by_seq.entry(*seq).or_insert(snapshot);
            }
            if let Some((_, newest)) = live_entry.applied_by_seq.last_key_value() {
                live_entry.current = newest.clone();
            }
        }
        self.next_applied_seq = self.next_applied_seq.max(committed.next_applied_seq);

        let mut applied = BTreeMap::new();
        for (seq, request_id) in self
            .applied_order
            .iter()
            .chain(committed.applied_order.iter())
            .filter(|(seq, _)| *seq >= reset_cursor)
        {
            applied.insert((*seq, request_id.clone()), ());
        }
        let mut retained = applied
            .into_keys()
            .rev()
            .take(CDP_EVENT_LOG_LIMIT)
            .collect::<Vec<_>>();
        retained.reverse();
        let retained_set = retained.iter().cloned().collect::<HashSet<_>>();
        self.applied_order = retained.iter().cloned().collect();
        for (request_id, entry) in &mut self.requests {
            entry
                .applied_by_seq
                .retain(|seq, _| retained_set.contains(&(*seq, request_id.clone())));
            if let Some((_, newest)) = entry.applied_by_seq.last_key_value() {
                entry.current = newest.clone();
            }
        }
    }
}

impl Default for NetworkRequestStore {
    fn default() -> Self {
        Self::new(0)
    }
}
#[derive(Default)]
struct AcceptedNavigationEpochs {
    by_sequence: BTreeMap<u64, u64>,
    floor_epoch: u64,
    low_water_mark: Option<u64>,
    last_accepted_sequence: Option<u64>,
}

impl AcceptedNavigationEpochs {
    fn accepts(&self, sequence: Option<u64>) -> bool {
        sequence.is_none_or(|sequence| {
            self.low_water_mark
                .is_none_or(|low_water_mark| low_water_mark < sequence)
                && self
                    .last_accepted_sequence
                    .is_none_or(|accepted| accepted < sequence)
        })
    }

    fn record(&mut self, sequence: Option<u64>, epoch: u64) {
        let Some(sequence) = sequence else {
            return;
        };
        debug_assert!(self.accepts(Some(sequence)));
        self.by_sequence.insert(sequence, epoch);
        self.last_accepted_sequence = Some(sequence);
    }

    fn epoch_for_observation(&self, sequence: Option<u64>, current_epoch: u64) -> u64 {
        let Some(sequence) = sequence else {
            return current_epoch;
        };
        self.by_sequence
            .range(..sequence)
            .next_back()
            .map_or(self.floor_epoch, |(_, epoch)| *epoch)
    }

    fn prune_through(&mut self, low_water_mark: u64) {
        if self
            .low_water_mark
            .is_some_and(|current| low_water_mark <= current)
        {
            return;
        }
        if let Some((_, epoch)) = self.by_sequence.range(..=low_water_mark).next_back() {
            self.floor_epoch = *epoch;
        }
        self.by_sequence
            .retain(|sequence, _| *sequence > low_water_mark);
        self.low_water_mark = Some(low_water_mark);
    }
}

enum NavigationEpochTransition {
    Rejected,
    Accepted { advanced: bool },
}

#[derive(Default)]
struct ConsoleRecordStore {
    navigation_epoch: u64,
    accepted_navigation_epochs: AcceptedNavigationEpochs,
    records: VecDeque<RustwrightConsoleRecord>,
    evictions_by_epoch: HashMap<u64, u64>,
    evictions_total: u64,
}

impl ConsoleRecordStore {
    fn record_navigation(&mut self, sequence: Option<u64>, epoch: u64) -> bool {
        if !self.accepted_navigation_epochs.accepts(sequence) {
            return false;
        }
        self.navigation_epoch = epoch;
        self.accepted_navigation_epochs.record(sequence, epoch);
        true
    }

    #[cfg(test)]
    fn advance_navigation(&mut self) {
        let epoch = self.navigation_epoch.saturating_add(1);
        let accepted = self.record_navigation(None, epoch);
        debug_assert!(accepted);
    }

    fn push(&mut self, record: RustwrightConsoleRecord, sequence: Option<u64>) {
        let navigation_epoch = self
            .accepted_navigation_epochs
            .epoch_for_observation(sequence, self.navigation_epoch);
        self.push_at_epoch(record, navigation_epoch);
    }

    fn push_capture_baseline(&mut self, record: RustwrightConsoleRecord) {
        self.push_at_epoch(record, 0);
    }

    fn push_at_epoch(&mut self, mut record: RustwrightConsoleRecord, navigation_epoch: u64) {
        record.navigation_epoch = navigation_epoch;
        if self.records.len() == NATIVE_CONSOLE_RECORD_CAPACITY {
            if let Some(evicted) = self.records.pop_front() {
                *self
                    .evictions_by_epoch
                    .entry(evicted.navigation_epoch)
                    .or_default() += 1;
                self.evictions_total = self.evictions_total.saturating_add(1);
            }
        }
        self.records.push_back(record);
    }

    fn prune_navigation_epochs_through(&mut self, low_water_mark: u64) {
        self.accepted_navigation_epochs
            .prune_through(low_water_mark);
    }

    fn read(
        &mut self,
        include_previous_navigations: bool,
        clear: bool,
    ) -> RustwrightConsoleRecords {
        let navigation_epoch = self.navigation_epoch;
        let records = self
            .records
            .iter()
            .filter(|record| {
                include_previous_navigations || record.navigation_epoch == navigation_epoch
            })
            .cloned()
            .collect::<Vec<_>>();
        let evicted = if include_previous_navigations {
            self.evictions_total
        } else {
            self.evictions_by_epoch
                .get(&navigation_epoch)
                .copied()
                .unwrap_or(0)
        };
        if clear {
            if include_previous_navigations {
                self.records.clear();
                self.evictions_by_epoch.clear();
                self.evictions_total = 0;
            } else {
                self.records
                    .retain(|record| record.navigation_epoch != navigation_epoch);
                let removed = self
                    .evictions_by_epoch
                    .remove(&navigation_epoch)
                    .unwrap_or(0);
                self.evictions_total = self.evictions_total.saturating_sub(removed);
            }
        }
        RustwrightConsoleRecords {
            records,
            navigation_epoch,
            evicted,
        }
    }
}

struct NativeNetworkRecordStore {
    navigation_epoch: u64,
    navigation_start_index: u64,
    current_loader_id: Option<String>,
    accepted_navigation_epochs: AcceptedNavigationEpochs,
    records: VecDeque<NativeNetworkEntry>,
    active_by_request: HashMap<(String, String), u64>,
    evictions_by_epoch: HashMap<u64, u64>,
}

#[derive(Clone)]
struct NativeNetworkEntry {
    record: RustwrightNetworkRecord,
    request_id: String,
    session_id: String,
    content_type: String,
    body_unavailable_reason: Option<String>,
}

struct NativeNetworkBodyRef {
    request_id: String,
    session_id: String,
    content_type: String,
    unavailable_reason: Option<String>,
    response_status: Option<u16>,
    completed: bool,
}

impl NativeNetworkRecordStore {
    fn new(navigation_start_index: u64) -> Self {
        Self {
            navigation_epoch: 0,
            navigation_start_index,
            current_loader_id: None,
            accepted_navigation_epochs: AcceptedNavigationEpochs::default(),
            records: VecDeque::with_capacity(NATIVE_NETWORK_RECORD_CAPACITY),
            active_by_request: HashMap::new(),
            evictions_by_epoch: HashMap::new(),
        }
    }

    fn begin_document_navigation(
        &mut self,
        loader_id: Option<&str>,
        start_index: u64,
        sequence: Option<u64>,
    ) -> NavigationEpochTransition {
        if !self.accepted_navigation_epochs.accepts(sequence) {
            return NavigationEpochTransition::Rejected;
        }
        let advanced = loader_id.is_none() || self.current_loader_id.as_deref() != loader_id;
        if advanced {
            self.navigation_epoch = self.navigation_epoch.saturating_add(1);
            self.navigation_start_index = start_index;
            self.current_loader_id = loader_id.map(ToString::to_string);
        }
        self.accepted_navigation_epochs
            .record(sequence, self.navigation_epoch);
        NavigationEpochTransition::Accepted { advanced }
    }

    fn begin_same_document_navigation(
        &mut self,
        start_index: u64,
        sequence: Option<u64>,
    ) -> NavigationEpochTransition {
        if !self.accepted_navigation_epochs.accepts(sequence) {
            return NavigationEpochTransition::Rejected;
        }
        self.navigation_epoch = self.navigation_epoch.saturating_add(1);
        self.navigation_start_index = start_index;
        self.accepted_navigation_epochs
            .record(sequence, self.navigation_epoch);
        NavigationEpochTransition::Accepted { advanced: true }
    }

    fn epoch_for_observation(&self, sequence: Option<u64>) -> u64 {
        self.accepted_navigation_epochs
            .epoch_for_observation(sequence, self.navigation_epoch)
    }

    fn prune_navigation_epochs_through(&mut self, low_water_mark: u64) {
        self.accepted_navigation_epochs
            .prune_through(low_water_mark);
    }

    fn push(&mut self, entry: NativeNetworkEntry) {
        if self.records.len() == NATIVE_NETWORK_RECORD_CAPACITY {
            if let Some(evicted) = self.records.pop_front() {
                let key = (evicted.session_id, evicted.request_id);
                if self.active_by_request.get(&key) == Some(&evicted.record.index) {
                    self.active_by_request.remove(&key);
                }
                *self
                    .evictions_by_epoch
                    .entry(evicted.record.navigation_epoch)
                    .or_default() += 1;
            }
        }
        let key = (entry.session_id.clone(), entry.request_id.clone());
        self.active_by_request.insert(key, entry.record.index);
        self.records.push_back(entry);
    }

    fn active_mut(
        &mut self,
        session_id: &str,
        request_id: &str,
    ) -> Option<&mut NativeNetworkEntry> {
        let index = self
            .active_by_request
            .get(&(session_id.to_owned(), request_id.to_owned()))
            .copied()?;
        self.records
            .iter_mut()
            .find(|entry| entry.record.index == index)
    }

    fn finish_redirect(&mut self, session_id: &str, request_id: &str, response: &Value) {
        if let Some(entry) = self.active_mut(session_id, request_id) {
            apply_native_network_response(entry, response);
            entry.record.completed = true;
            entry.body_unavailable_reason =
                Some("redirect response body is unavailable".to_owned());
        }
    }

    fn read(
        &mut self,
        include_previous_navigations: bool,
        clear: bool,
    ) -> RustwrightNetworkRecords {
        let navigation_epoch = self.navigation_epoch;
        let records = self
            .records
            .iter()
            .filter(|entry| {
                include_previous_navigations || entry.record.navigation_epoch == navigation_epoch
            })
            .map(|entry| entry.record.clone())
            .collect::<Vec<_>>();
        let evicted = if include_previous_navigations {
            self.evictions_by_epoch.values().copied().sum()
        } else {
            self.evictions_by_epoch
                .get(&navigation_epoch)
                .copied()
                .unwrap_or(0)
        };
        if clear {
            if include_previous_navigations {
                self.records.clear();
                self.active_by_request.clear();
                self.evictions_by_epoch.clear();
            } else {
                let removed = self
                    .records
                    .iter()
                    .filter(|entry| entry.record.navigation_epoch == navigation_epoch)
                    .map(|entry| {
                        (
                            (entry.session_id.clone(), entry.request_id.clone()),
                            entry.record.index,
                        )
                    })
                    .collect::<Vec<_>>();
                self.records
                    .retain(|entry| entry.record.navigation_epoch != navigation_epoch);
                for (key, index) in removed {
                    if self.active_by_request.get(&key) == Some(&index) {
                        self.active_by_request.remove(&key);
                    }
                }
                self.evictions_by_epoch.remove(&navigation_epoch);
            }
        }
        RustwrightNetworkRecords {
            records,
            navigation_epoch,
            navigation_start_index: self.navigation_start_index,
            evicted,
        }
    }

    fn body_ref(&self, index: u64) -> Option<NativeNetworkBodyRef> {
        self.records
            .iter()
            .find(|entry| entry.record.index == index)
            .map(|entry| NativeNetworkBodyRef {
                request_id: entry.request_id.clone(),
                session_id: entry.session_id.clone(),
                content_type: entry.content_type.clone(),
                unavailable_reason: entry.body_unavailable_reason.clone(),
                response_status: entry.record.response_status,
                completed: entry.record.completed,
            })
    }
}

fn metadata_headers(value: Option<&Value>) -> Vec<(String, String)> {
    let Some(headers) = value.and_then(Value::as_object) else {
        return Vec::new();
    };
    headers
        .iter()
        .map(|(name, value)| {
            (
                name.clone(),
                value
                    .as_str()
                    .map(ToString::to_string)
                    .unwrap_or_else(|| value.to_string()),
            )
        })
        .collect()
}

fn header_content_type(headers: &[(String, String)]) -> String {
    headers
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("content-type"))
        .map(|(_, value)| {
            value
                .split(';')
                .next()
                .unwrap_or_default()
                .trim()
                .to_ascii_lowercase()
        })
        .unwrap_or_default()
}

fn is_text_content_type(content_type: &str) -> bool {
    content_type.starts_with("text/")
        || content_type.ends_with("+json")
        || content_type.ends_with("+xml")
        || matches!(
            content_type,
            "application/json"
                | "application/xml"
                | "application/javascript"
                | "application/x-javascript"
                | "application/x-www-form-urlencoded"
        )
}

fn bounded_network_text_body(bytes: &[u8], max_bytes: usize) -> RustwrightNetworkBody {
    let total_bytes = bytes.len();
    let delivered_bytes = total_bytes
        .min(max_bytes)
        .min(NATIVE_NETWORK_BODY_MAX_BYTES);
    RustwrightNetworkBody::Text {
        text: String::from_utf8_lossy(&bytes[..delivered_bytes]).into_owned(),
        total_bytes,
        truncated: delivered_bytes < total_bytes,
    }
}

fn apply_native_network_response(entry: &mut NativeNetworkEntry, response: &Value) {
    entry.record.response_status =
        response
            .get("status")
            .and_then(Value::as_f64)
            .and_then(|status| {
                (0.0..=f64::from(u16::MAX))
                    .contains(&status)
                    .then_some(status as u16)
            });
    entry.record.response_headers = metadata_headers(response.get("headers"));
    entry.content_type = header_content_type(&entry.record.response_headers);
    if entry.content_type.is_empty() {
        entry.content_type = response
            .get("mimeType")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_ascii_lowercase();
    }
}

fn apply_native_network_response_extra_info(entry: &mut NativeNetworkEntry, params: &Value) {
    entry.record.response_status =
        params
            .get("statusCode")
            .and_then(Value::as_f64)
            .and_then(|status| {
                (0.0..=f64::from(u16::MAX))
                    .contains(&status)
                    .then_some(status as u16)
            });
    entry.record.response_headers = metadata_headers(params.get("headers"));
    let content_type = header_content_type(&entry.record.response_headers);
    if !content_type.is_empty() {
        entry.content_type = content_type;
    }
}

#[derive(Clone)]
struct NetworkRequestEntry {
    current: NetworkRequestSnapshot,
    applied_by_seq: BTreeMap<u64, NetworkRequestSnapshot>,
}

#[derive(Clone, Debug)]
struct PageFrameRecord {
    id: String,
    parent_id: Option<String>,
    name: String,
    url: String,
    session_id: Option<String>,
    name_stamp: Option<FrameMetadataStamp>,
    url_stamp: Option<FrameMetadataStamp>,
}

#[derive(Clone, Debug)]
struct FrameMetadataStamp {
    session_id: String,
    attachment_generation: Option<u64>,
    source: FrameMetadataSource,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FrameMetadataSource {
    TargetInfo,
    FrameObservation,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct FrameSessionPin {
    session_id: String,
    generation: u64,
}

enum FrameSessionOwnershipClaim {
    Claimed(FrameSessionPin),
    Existing(FrameSessionPin),
}

#[derive(Clone, Debug)]
struct FrameSwapLink {
    losing_session_id: String,
    losing_generation: u64,
    successor_generation: Option<u64>,
    losing_detach_consumed: bool,
}

#[derive(Clone, Debug)]
struct FrameSwapState {
    // Ordered swap edges preserve ancestry across successions. A waiter pinned to any losing
    // generation follows the connected chain until its current descendant becomes ready or the
    // lineage is terminally invalidated.
    lineage: Vec<FrameSwapLink>,
    successor_ready: bool,
}

#[derive(Debug)]
struct AuthoritativeFrameRecord {
    id: String,
    parent_id: Option<String>,
    name: Option<String>,
    url: Option<String>,
    session_id: String,
}

#[derive(Debug)]
struct AuthoritativeFrameTree {
    root_frame_id: String,
    frames: HashMap<String, AuthoritativeFrameRecord>,
    child_order: HashMap<String, Vec<String>>,
    frame_loader_ids: HashMap<String, String>,
    frame_sessions: HashMap<String, String>,
    session_roots: HashMap<String, String>,
}

#[derive(Debug, Default)]
struct AuthoritativeFrameTreeCommitEffects {
    ownership_changed: bool,
    removed_setup_generations: Vec<u64>,
}

#[derive(Debug)]
struct PageFrameState {
    main_session_id: String,
    frame_sessions: HashMap<String, String>,
    frame_attachment_generations: HashMap<String, u64>,
    frame_swaps: HashMap<String, FrameSwapState>,
    frame_session_waiters: HashMap<String, HashMap<u64, usize>>,
    frame_attachment_locks: HashMap<String, Arc<tokio::sync::Mutex<()>>>,
    next_attachment_generation: u64,
    session_frames: HashMap<String, String>,
    frames: HashMap<String, PageFrameRecord>,
    child_order: HashMap<String, Vec<String>>,
    frame_loader_ids: HashMap<String, String>,
    execution_contexts: HashMap<(String, String), Value>,
    frame_session_errors: HashMap<String, String>,
    iframe_sessions_armed: HashSet<String>,
    iframe_sessions_routable: HashSet<String>,
    iframe_sessions_ready: HashSet<String>,
    iframe_setup_started: HashSet<String>,
    frame_event_listener_registered: bool,
    page_domain_enabled_sessions: HashSet<String>,
    frame_tree_populated_sessions: HashSet<String>,
    frame_tree_dirty_sessions: HashSet<String>,
    frame_tree_generations: HashMap<String, u64>,
    frame_invalidation_sequences: HashMap<String, u64>,
    frame_ownership_generation: u64,
    frame_event_cursor: u64,
    #[cfg(test)]
    locator_resolution_reresolve_count: u64,
    frame_tree_refresh_lock: Arc<tokio::sync::Mutex<()>>,
    session_updates: watch::Sender<u64>,
}

impl PageFrameState {
    fn new(main_session_id: String) -> Self {
        let (session_updates, _) = watch::channel(0);
        Self {
            main_session_id,
            frame_sessions: HashMap::new(),
            frame_attachment_generations: HashMap::new(),
            frame_swaps: HashMap::new(),
            frame_session_waiters: HashMap::new(),
            frame_attachment_locks: HashMap::new(),
            next_attachment_generation: 0,
            session_frames: HashMap::new(),
            frames: HashMap::new(),
            child_order: HashMap::new(),
            frame_loader_ids: HashMap::new(),
            execution_contexts: HashMap::new(),
            frame_session_errors: HashMap::new(),
            iframe_sessions_armed: HashSet::new(),
            iframe_sessions_routable: HashSet::new(),
            iframe_sessions_ready: HashSet::new(),
            iframe_setup_started: HashSet::new(),
            frame_event_listener_registered: false,
            page_domain_enabled_sessions: HashSet::new(),
            frame_tree_populated_sessions: HashSet::new(),
            frame_tree_dirty_sessions: HashSet::new(),
            frame_tree_generations: HashMap::new(),
            frame_invalidation_sequences: HashMap::new(),
            frame_ownership_generation: 0,
            frame_event_cursor: 0,
            #[cfg(test)]
            locator_resolution_reresolve_count: 0,
            frame_tree_refresh_lock: Arc::new(tokio::sync::Mutex::new(())),
            session_updates,
        }
    }

    fn set_frame_event_cursor(&mut self, cursor: u64) {
        self.frame_event_cursor = cursor;
    }

    fn mark_frame_event_listener_registered(&mut self) {
        self.frame_event_listener_registered = true;
        self.mark_all_frame_caches_dirty();
    }

    fn mark_page_domain_enabled(&mut self, session_id: &str) {
        self.page_domain_enabled_sessions
            .insert(session_id.to_string());
        self.mark_frame_cache_dirty(session_id);
    }

    fn mark_frame_cache_dirty(&mut self, session_id: &str) {
        let generation = self
            .frame_tree_generations
            .entry(session_id.to_string())
            .or_default();
        advance_lifetime_counter(generation);
        self.frame_tree_dirty_sessions
            .insert(session_id.to_string());
    }
    fn mark_frame_cache_dirty_at_sequence(
        &mut self,
        session_id: &str,
        sequence: Option<u64>,
    ) -> bool {
        if let Some(sequence) = sequence {
            if self
                .frame_invalidation_sequences
                .get(session_id)
                .is_some_and(|last_sequence| *last_sequence >= sequence)
            {
                return false;
            }
            self.frame_invalidation_sequences
                .insert(session_id.to_string(), sequence);
        }
        self.mark_frame_cache_dirty(session_id);
        true
    }

    fn mark_all_frame_caches_dirty(&mut self) {
        for session_id in self.session_ids() {
            self.mark_frame_cache_dirty(&session_id);
        }
    }

    fn frame_cache_refresh_generation(&self, session_id: &str) -> Option<u64> {
        let trusted = self.frame_event_listener_registered
            && self.page_domain_enabled_sessions.contains(session_id);
        let populated = self.frame_tree_populated_sessions.contains(session_id);
        let dirty = self.frame_tree_dirty_sessions.contains(session_id);
        (!trusted || !populated || dirty).then(|| {
            self.frame_tree_generations
                .get(session_id)
                .copied()
                .unwrap_or(0)
        })
    }

    fn mark_frame_tree_refreshed(&mut self, session_id: &str, generation: u64) {
        self.frame_tree_populated_sessions
            .insert(session_id.to_string());
        let generation_is_current = self
            .frame_tree_generations
            .get(session_id)
            .copied()
            .unwrap_or(0)
            == generation;
        if self.frame_event_listener_registered
            && self.page_domain_enabled_sessions.contains(session_id)
            && generation_is_current
        {
            self.frame_tree_dirty_sessions.remove(session_id);
        }
    }

    fn forget_frame_session_cache(&mut self, session_id: &str) {
        self.page_domain_enabled_sessions.remove(session_id);
        self.frame_tree_populated_sessions.remove(session_id);
        self.frame_tree_dirty_sessions.remove(session_id);
        self.frame_tree_generations.remove(session_id);
        self.frame_invalidation_sequences.remove(session_id);
        self.invalidate_execution_contexts_for_session(session_id);
    }

    fn subscribe_session_updates(&self) -> watch::Receiver<u64> {
        self.session_updates.subscribe()
    }

    fn notify_session_update(&self) {
        self.session_updates.send_modify(advance_lifetime_counter);
    }

    fn record_frame_session_error(&mut self, frame_id: &str, error: String) {
        self.frame_session_errors
            .insert(frame_id.to_string(), error);
        self.notify_session_update();
    }

    fn session_still_owns_frame(&self, frame_id: &str, session_id: &str) -> bool {
        self.session_frames.get(session_id).map(String::as_str) == Some(frame_id)
            && self.frame_sessions.get(frame_id).map(String::as_str) == Some(session_id)
    }

    fn session_owns_frame(&self, frame_id: &str, session_id: &str) -> bool {
        self.owns_session(session_id)
            && self.frame_sessions.get(frame_id).map(String::as_str) == Some(session_id)
    }

    fn cached_execution_context(&self, frame_id: &str, session_id: &str) -> Option<Value> {
        self.execution_contexts
            .get(&(session_id.to_string(), frame_id.to_string()))
            .cloned()
    }

    fn cache_execution_context(
        &mut self,
        frame_id: &str,
        session_id: &str,
        context_id: Value,
    ) -> bool {
        if !self.session_owns_frame(frame_id, session_id) {
            return false;
        }
        self.execution_contexts
            .insert((session_id.to_string(), frame_id.to_string()), context_id);
        true
    }

    fn invalidate_execution_context(&mut self, session_id: &str, context_id: &Value) {
        self.execution_contexts
            .retain(|(cached_session_id, _), cached_context_id| {
                cached_session_id != session_id || cached_context_id != context_id
            });
    }

    fn invalidate_execution_contexts_for_frame(&mut self, frame_id: &str) {
        self.execution_contexts
            .retain(|(_, cached_frame_id), _| cached_frame_id != frame_id);
    }

    fn invalidate_execution_contexts_for_session(&mut self, session_id: &str) {
        self.execution_contexts
            .retain(|(cached_session_id, _), _| cached_session_id != session_id);
    }

    fn record_frame_loader(&mut self, frame_id: &str, loader_id: Option<&str>) {
        let Some(loader_id) = loader_id else {
            return;
        };
        let previous = self
            .frame_loader_ids
            .insert(frame_id.to_string(), loader_id.to_string());
        if previous
            .as_deref()
            .is_some_and(|previous| previous != loader_id)
        {
            self.invalidate_execution_contexts_for_frame(frame_id);
        }
    }

    fn record_frame_swap(&mut self, frame_id: &str) {
        self.invalidate_execution_contexts_for_frame(frame_id);
        advance_lifetime_counter(&mut self.frame_ownership_generation);
    }

    fn frame_swap_event_completes_adoption(&self, frame_id: &str, event_session_id: &str) -> bool {
        self.frame_sessions.get(frame_id).is_some_and(|owner| {
            owner != event_session_id
                && owner != &self.main_session_id
                && self.session_still_owns_frame(frame_id, owner)
        })
    }

    fn session_pin_for_frame(&self, frame_id: &str) -> Option<FrameSessionPin> {
        Some(FrameSessionPin {
            session_id: self.frame_sessions.get(frame_id)?.clone(),
            generation: *self.frame_attachment_generations.get(frame_id)?,
        })
    }

    fn session_pin_still_owns_frame(&self, frame_id: &str, pin: &FrameSessionPin) -> bool {
        self.session_still_owns_frame(frame_id, &pin.session_id)
            && self.frame_attachment_generations.get(frame_id) == Some(&pin.generation)
    }

    fn routable_session_pin_for_frame(
        &self,
        frame_id: &str,
        different_from_session_id: Option<&str>,
    ) -> Option<FrameSessionPin> {
        let pin = self.session_pin_for_frame(frame_id)?;
        let is_routable = pin.session_id == self.main_session_id
            || self.iframe_sessions_routable.contains(&pin.session_id);
        (is_routable
            && different_from_session_id != Some(pin.session_id.as_str())
            && self.session_pin_still_owns_frame(frame_id, &pin))
        .then_some(pin)
    }

    fn attachment_lock_for_frame(&mut self, frame_id: &str) -> Arc<tokio::sync::Mutex<()>> {
        Arc::clone(
            self.frame_attachment_locks
                .entry(frame_id.to_string())
                .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(()))),
        )
    }
    fn reclaim_attachment_lock(
        &mut self,
        frame_id: &str,
        attachment_lock: &Arc<tokio::sync::Mutex<()>>,
    ) {
        let reclaimable = !self.frames.contains_key(frame_id)
            && self
                .frame_attachment_locks
                .get(frame_id)
                .is_some_and(|stored| {
                    Arc::ptr_eq(stored, attachment_lock) && Arc::strong_count(stored) == 2
                });
        if reclaimable {
            self.frame_attachment_locks.remove(frame_id);
        }
    }

    fn claim_manual_session_for_frame(
        &mut self,
        frame_id: &str,
        session_id: &str,
    ) -> FrameSessionOwnershipClaim {
        if let Some(existing) = self
            .session_pin_for_frame(frame_id)
            .filter(|pin| self.session_pin_still_owns_frame(frame_id, pin))
        {
            return FrameSessionOwnershipClaim::Existing(existing);
        }
        FrameSessionOwnershipClaim::Claimed(self.record_session_for_frame(frame_id, session_id))
    }

    fn swap_replaces_pin(&self, frame_id: &str, pin: &FrameSessionPin) -> bool {
        self.frame_swaps.get(frame_id).is_some_and(|swap| {
            swap.lineage
                .iter()
                .any(|link| link.losing_generation == pin.generation)
        })
    }

    fn register_frame_session_waiter(&mut self, frame_id: &str, generation: u64) {
        let count = self
            .frame_session_waiters
            .entry(frame_id.to_string())
            .or_default()
            .entry(generation)
            .or_default();
        *count = count.checked_add(1).expect("frame waiter count overflow");
    }

    fn unregister_frame_session_waiter(&mut self, frame_id: &str, generation: u64) {
        let remove_frame_entry = if let Some(waiters) = self.frame_session_waiters.get_mut(frame_id)
        {
            if let Some(count) = waiters.get_mut(&generation) {
                *count = count.saturating_sub(1);
                if *count == 0 {
                    waiters.remove(&generation);
                }
            }
            waiters.is_empty()
        } else {
            false
        };
        if remove_frame_entry {
            self.frame_session_waiters.remove(frame_id);
        }
        self.retire_ready_frame_swap(frame_id);
    }

    fn retire_ready_frame_swap(&mut self, frame_id: &str) {
        let Some(swap) = self.frame_swaps.get(frame_id) else {
            return;
        };
        if !swap.successor_ready {
            return;
        }
        let has_lineage_waiter = self
            .frame_session_waiters
            .get(frame_id)
            .is_some_and(|waiters| {
                waiters.keys().any(|generation| {
                    swap.lineage.iter().any(|link| {
                        link.losing_generation == *generation
                            || link.successor_generation == Some(*generation)
                    })
                })
            });
        if !has_lineage_waiter {
            self.frame_swaps.remove(frame_id);
        }
    }

    fn session_is_pending_swap_loser(&self, session_id: &str) -> bool {
        self.frame_swaps.values().any(|swap| {
            !swap.successor_ready
                && swap
                    .lineage
                    .iter()
                    .any(|link| link.losing_session_id == session_id)
        })
    }
    fn setup_generations_for_session(&self, session_id: &str) -> Vec<u64> {
        let mut generations = self
            .frame_sessions
            .iter()
            .filter_map(|(frame_id, owner)| {
                (owner == session_id)
                    .then(|| self.frame_attachment_generations.get(frame_id).copied())
                    .flatten()
            })
            .collect::<Vec<_>>();
        for generation in self.frame_swaps.values().flat_map(|swap| {
            swap.lineage.iter().filter_map(|link| {
                (link.losing_session_id == session_id).then_some(link.losing_generation)
            })
        }) {
            if !generations.contains(&generation) {
                generations.push(generation);
            }
        }
        generations
    }

    fn invalidate_iframe_session_markers(&mut self, session_id: &str) {
        self.iframe_sessions_armed.remove(session_id);
        self.iframe_sessions_routable.remove(session_id);
        self.iframe_sessions_ready.remove(session_id);
        self.iframe_setup_started.remove(session_id);
    }

    fn record_frame_session_error_if_current(
        &mut self,
        frame_id: &str,
        pin: &FrameSessionPin,
        error: String,
    ) {
        if self.session_pin_still_owns_frame(frame_id, pin) {
            self.record_frame_session_error(frame_id, error);
        }
    }

    fn claim_iframe_session_setup(
        &mut self,
        frame_id: &str,
        pin: &FrameSessionPin,
    ) -> Option<bool> {
        if !self.session_pin_still_owns_frame(frame_id, pin) {
            return None;
        }
        self.iframe_sessions_armed.insert(pin.session_id.clone());
        self.notify_session_update();
        Some(self.iframe_setup_started.insert(pin.session_id.clone()))
    }

    fn mark_iframe_session_ready(&mut self, frame_id: &str, pin: &FrameSessionPin) {
        if self.session_pin_still_owns_frame(frame_id, pin)
            && self.iframe_sessions_routable.contains(&pin.session_id)
        {
            self.iframe_sessions_ready.insert(pin.session_id.clone());
            if let Some(swap) = self.frame_swaps.get_mut(frame_id) {
                if swap
                    .lineage
                    .last()
                    .is_some_and(|link| link.successor_generation == Some(pin.generation))
                {
                    swap.successor_ready = true;
                }
            }
            self.retire_ready_frame_swap(frame_id);
            self.notify_session_update();
        }
    }

    #[cfg(test)]
    fn mark_iframe_session_ready_for_session(&mut self, frame_id: &str, session_id: &str) {
        let Some(pin) = self
            .session_pin_for_frame(frame_id)
            .filter(|pin| pin.session_id == session_id)
        else {
            return;
        };
        self.iframe_sessions_routable.insert(session_id.to_string());
        self.mark_iframe_session_ready(frame_id, &pin);
    }

    fn mark_iframe_session_routable(
        &mut self,
        frame_id: &str,
        pin: &FrameSessionPin,
        focus_enqueued: FocusEmulationEnqueueReceipt,
    ) -> bool {
        if focus_enqueued.session_id != pin.session_id
            || !self.session_pin_still_owns_frame(frame_id, pin)
        {
            return false;
        }
        // This is the sole publication point for iframe routability. Requiring the
        // session-bound receipt makes it impossible to wake a resolver until the focus
        // command has already been queued into that session's transport FIFO.
        self.iframe_sessions_routable.insert(pin.session_id.clone());
        focus_enqueued.absorb_response();
        self.notify_session_update();
        true
    }

    fn owns_session(&self, session_id: &str) -> bool {
        session_id == self.main_session_id || self.session_frames.contains_key(session_id)
    }

    fn refresh_registration(&self, session_id: &str) -> Option<(Option<String>, u64)> {
        self.owns_session(session_id).then(|| {
            (
                self.session_frames.get(session_id).cloned(),
                self.frame_ownership_generation,
            )
        })
    }

    fn refresh_registration_is_current(
        &self,
        session_id: &str,
        root_frame_id: Option<&str>,
        ownership_generation: u64,
        tree_generation: u64,
    ) -> bool {
        self.owns_session(session_id)
            && self.session_frames.get(session_id).map(String::as_str) == root_frame_id
            && self.frame_ownership_generation == ownership_generation
            && self
                .frame_tree_generations
                .get(session_id)
                .copied()
                .unwrap_or(0)
                == tree_generation
    }

    #[cfg(test)]
    fn record_locator_resolution_reresolve(&mut self) {
        advance_lifetime_counter(&mut self.locator_resolution_reresolve_count);
    }
    fn registered_root_sessions(&self) -> HashMap<String, String> {
        self.session_frames
            .iter()
            .map(|(session_id, frame_id)| (frame_id.clone(), session_id.clone()))
            .collect()
    }

    fn apply_authoritative_frame_tree(
        &mut self,
        refreshed_session_id: &str,
        mut tree: AuthoritativeFrameTree,
    ) -> AuthoritativeFrameTreeCommitEffects {
        let ownership_generation_before = self.frame_ownership_generation;
        let authoritative_frame_ids = tree.frames.keys().cloned().collect::<HashSet<_>>();
        let mut removed_frame_ids = HashSet::new();
        let mut pending_removals = self
            .frame_sessions
            .iter()
            .filter_map(|(frame_id, session_id)| {
                (session_id == refreshed_session_id && !authoritative_frame_ids.contains(frame_id))
                    .then_some(frame_id.clone())
            })
            .collect::<Vec<_>>();
        while let Some(frame_id) = pending_removals.pop() {
            if authoritative_frame_ids.contains(&frame_id)
                || !removed_frame_ids.insert(frame_id.clone())
            {
                continue;
            }
            if let Some(children) = self.child_order.get(&frame_id) {
                pending_removals.extend(children.iter().cloned());
            }
        }

        let removed_session_ids = self
            .session_frames
            .iter()
            .filter_map(|(session_id, frame_id)| {
                removed_frame_ids
                    .contains(frame_id)
                    .then_some(session_id.clone())
            })
            .collect::<HashSet<_>>();
        let mut invalidated_frame_ids = removed_frame_ids.clone();
        let mut dirty_session_ids = HashSet::new();

        for frame_id in &removed_frame_ids {
            if let Some(session_id) = self.frame_sessions.get(frame_id) {
                if session_id != refreshed_session_id {
                    dirty_session_ids.insert(session_id.clone());
                }
            }
        }
        for (frame_id, session_id) in &tree.frame_sessions {
            if self.frame_sessions.get(frame_id) != Some(session_id) {
                invalidated_frame_ids.insert(frame_id.clone());
                if let Some(previous_session_id) = self.frame_sessions.get(frame_id) {
                    if previous_session_id != refreshed_session_id {
                        dirty_session_ids.insert(previous_session_id.clone());
                    }
                }
            }
        }
        let mut removed_setup_generations = removed_frame_ids
            .iter()
            .filter_map(|frame_id| self.frame_attachment_generations.get(frame_id).copied())
            .collect::<Vec<_>>();
        for (frame_id, session_id) in &tree.frame_sessions {
            if self
                .frame_sessions
                .get(frame_id)
                .is_some_and(|previous_session_id| previous_session_id != session_id)
            {
                if let Some(generation) = self.frame_attachment_generations.get(frame_id).copied() {
                    if !removed_setup_generations.contains(&generation) {
                        removed_setup_generations.push(generation);
                    }
                }
            }
        }
        for (frame_id, loader_id) in &tree.frame_loader_ids {
            if self
                .frame_loader_ids
                .get(frame_id)
                .is_some_and(|previous| previous != loader_id)
            {
                invalidated_frame_ids.insert(frame_id.clone());
            }
        }

        // Rebuild every authoritative descendant edge in one pass. The root
        // frame's incoming edge belongs to its parent session, so refreshing
        // an OOPIF child session must preserve that cross-session edge.
        // Existing foreign-session children omitted by this tree also remain.
        for children in self.child_order.values_mut() {
            children.retain(|child_id| {
                !removed_frame_ids.contains(child_id)
                    && (child_id == &tree.root_frame_id
                        || !authoritative_frame_ids.contains(child_id))
            });
        }
        self.child_order
            .retain(|parent_id, _| !removed_frame_ids.contains(parent_id));
        for (parent_id, mut children) in std::mem::take(&mut tree.child_order) {
            if let Some(mut preserved_children) = self.child_order.remove(&parent_id) {
                children.append(&mut preserved_children);
            }
            self.child_order.insert(parent_id, children);
        }

        for frame_id in &removed_frame_ids {
            self.invalidate_frame_attachment(frame_id);
        }
        self.frames
            .retain(|frame_id, _| !removed_frame_ids.contains(frame_id));
        self.frame_sessions
            .retain(|frame_id, _| !removed_frame_ids.contains(frame_id));
        self.frame_loader_ids
            .retain(|frame_id, _| !removed_frame_ids.contains(frame_id));
        self.frame_session_errors
            .retain(|frame_id, _| !removed_frame_ids.contains(frame_id));
        self.session_frames
            .retain(|_, frame_id| !removed_frame_ids.contains(frame_id));

        for session_id in &removed_session_ids {
            self.iframe_sessions_armed.remove(session_id);
            self.iframe_sessions_ready.remove(session_id);
            self.iframe_setup_started.remove(session_id);
            self.page_domain_enabled_sessions.remove(session_id);
            self.frame_tree_populated_sessions.remove(session_id);
            self.frame_tree_dirty_sessions.remove(session_id);
            self.frame_tree_generations.remove(session_id);
            self.frame_invalidation_sequences.remove(session_id);
        }

        let session_roots = tree.session_roots.drain().collect::<Vec<_>>();
        let root_frame_ids = session_roots
            .iter()
            .map(|(_, frame_id)| frame_id.clone())
            .collect::<HashSet<_>>();
        for (session_id, root_frame_id) in session_roots {
            if session_id == self.main_session_id {
                let ownership_changed = self
                    .frame_sessions
                    .insert(root_frame_id.clone(), session_id.clone())
                    .as_deref()
                    != Some(session_id.as_str());
                if ownership_changed {
                    self.invalidate_execution_contexts_for_frame(&root_frame_id);
                    advance_lifetime_counter(&mut self.frame_ownership_generation);
                }
            } else {
                self.record_session_for_frame(&root_frame_id, &session_id);
            }
        }
        let mut descendant_ownership_changed = false;
        for (frame_id, session_id) in tree.frame_sessions.drain() {
            if root_frame_ids.contains(&frame_id) {
                continue;
            }
            let ownership_changed = self
                .frame_sessions
                .insert(frame_id.clone(), session_id.clone())
                .as_deref()
                != Some(session_id.as_str());
            if ownership_changed {
                self.invalidate_execution_contexts_for_frame(&frame_id);
                descendant_ownership_changed = true;
            }
        }
        if descendant_ownership_changed {
            advance_lifetime_counter(&mut self.frame_ownership_generation);
        }
        for (_, incoming) in tree.frames.drain() {
            self.record_frame(
                incoming.id,
                incoming.parent_id,
                incoming.name,
                incoming.url,
                incoming.session_id,
            );
        }
        self.frame_loader_ids.extend(tree.frame_loader_ids.drain());
        self.execution_contexts.retain(|(session_id, frame_id), _| {
            !removed_session_ids.contains(session_id) && !invalidated_frame_ids.contains(frame_id)
        });

        for session_id in dirty_session_ids {
            if self.owns_session(&session_id) {
                self.mark_frame_cache_dirty(&session_id);
            }
        }
        let ownership_changed = self.frame_ownership_generation != ownership_generation_before;
        AuthoritativeFrameTreeCommitEffects {
            ownership_changed,
            removed_setup_generations,
        }
    }

    fn session_ids(&self) -> Vec<String> {
        let mut sessions = vec![self.main_session_id.clone()];
        for session_id in self
            .session_frames
            .keys()
            .filter(|session_id| self.iframe_sessions_ready.contains(*session_id))
        {
            if !sessions.iter().any(|existing| existing == session_id) {
                sessions.push(session_id.clone());
            }
        }
        sessions
    }

    fn record_session_for_frame(&mut self, frame_id: &str, session_id: &str) -> FrameSessionPin {
        self.record_session_for_frame_at_sequence(frame_id, session_id, None)
    }

    fn record_session_for_frame_at_sequence(
        &mut self,
        frame_id: &str,
        session_id: &str,
        sequence: Option<u64>,
    ) -> FrameSessionPin {
        let session_changed =
            self.frame_sessions.get(frame_id).map(String::as_str) != Some(session_id);
        if session_changed {
            self.frame_session_errors.remove(frame_id);
        }
        let continues_swap = self
            .frame_swaps
            .get(frame_id)
            .is_some_and(|swap| !swap.successor_ready);
        if !continues_swap && session_changed {
            self.frame_swaps.remove(frame_id);
        }
        if session_changed || !self.frame_attachment_generations.contains_key(frame_id) {
            self.next_attachment_generation = self
                .next_attachment_generation
                .checked_add(1)
                .expect("frame attachment generation overflow");
            self.frame_attachment_generations
                .insert(frame_id.to_string(), self.next_attachment_generation);
        }
        let previous_session_id = self
            .frame_sessions
            .insert(frame_id.to_string(), session_id.to_string());
        if let Some(previous_session_id) = previous_session_id.as_deref() {
            if previous_session_id != session_id {
                self.invalidate_iframe_session_markers(previous_session_id);
                if self
                    .session_frames
                    .get(previous_session_id)
                    .map(String::as_str)
                    == Some(frame_id)
                {
                    self.session_frames.remove(previous_session_id);
                }
            }
        }
        if let Some(previous_frame_id) = self
            .session_frames
            .insert(session_id.to_string(), frame_id.to_string())
        {
            if previous_frame_id != frame_id {
                self.invalidate_iframe_session_markers(session_id);
                if self
                    .frame_sessions
                    .get(&previous_frame_id)
                    .map(String::as_str)
                    == Some(session_id)
                {
                    self.frame_sessions.remove(&previous_frame_id);
                    self.frame_attachment_generations.remove(&previous_frame_id);
                    self.frame_session_errors.remove(&previous_frame_id);
                    self.frame_swaps.remove(&previous_frame_id);
                    self.invalidate_execution_contexts_for_frame(&previous_frame_id);
                }
            }
        }
        if continues_swap {
            let generation = *self
                .frame_attachment_generations
                .get(frame_id)
                .expect("swap successor must have an attachment generation");
            if let Some(swap) = self.frame_swaps.get_mut(frame_id) {
                swap.lineage
                    .last_mut()
                    .expect("pending swap must have a lineage link")
                    .successor_generation = Some(generation);
            }
        }
        if let Some(record) = self.frames.get_mut(frame_id) {
            record.session_id = Some(session_id.to_string());
        }
        if session_changed {
            self.invalidate_execution_contexts_for_frame(frame_id);
            advance_lifetime_counter(&mut self.frame_ownership_generation);
            if let Some(previous_session_id) = previous_session_id {
                self.mark_frame_cache_dirty_at_sequence(&previous_session_id, sequence);
                if previous_session_id != self.main_session_id
                    && !self.session_frames.contains_key(&previous_session_id)
                {
                    self.forget_frame_session_cache(&previous_session_id);
                }
            }
            self.mark_frame_cache_dirty_at_sequence(session_id, sequence);
        }
        self.session_pin_for_frame(frame_id)
            .expect("recorded frame session must have an attachment generation")
    }

    fn invalidate_frame_attachment(&mut self, frame_id: &str) -> Option<String> {
        if self.frame_attachment_generations.remove(frame_id).is_some() {
            self.next_attachment_generation = self
                .next_attachment_generation
                .checked_add(1)
                .expect("frame attachment generation overflow");
        }
        self.frame_swaps.remove(frame_id);
        self.frame_session_errors.remove(frame_id);
        self.frame_loader_ids.remove(frame_id);
        self.invalidate_execution_contexts_for_frame(frame_id);
        if let Some(record) = self.frames.get_mut(frame_id) {
            record.session_id = None;
        }
        let session_id = self.frame_sessions.remove(frame_id)?;
        advance_lifetime_counter(&mut self.frame_ownership_generation);
        if self.session_frames.get(&session_id).map(String::as_str) == Some(frame_id) {
            self.session_frames.remove(&session_id);
        }
        if !self
            .frame_sessions
            .values()
            .any(|owner| owner == &session_id)
        {
            self.invalidate_iframe_session_markers(&session_id);
            if session_id != self.main_session_id {
                self.forget_frame_session_cache(&session_id);
            }
        }
        Some(session_id)
    }

    fn remap_detached_session_ownership(
        &mut self,
        detached_session_id: &str,
        sequence: Option<u64>,
    ) {
        let root_frame_id = self.session_frames.get(detached_session_id).cloned();
        let replacement_session_id = root_frame_id
            .as_deref()
            .and_then(|frame_id| self.frames.get(frame_id))
            .and_then(|record| record.parent_id.as_deref())
            .and_then(|parent_id| self.frame_sessions.get(parent_id))
            .filter(|session_id| session_id.as_str() != detached_session_id)
            .cloned()
            .unwrap_or_else(|| self.main_session_id.clone());
        let remapped_frame_ids = self
            .frame_sessions
            .iter()
            .filter_map(|(frame_id, session_id)| {
                (session_id == detached_session_id).then_some(frame_id.clone())
            })
            .collect::<Vec<_>>();
        for frame_id in remapped_frame_ids {
            self.invalidate_frame_attachment(&frame_id);
            self.next_attachment_generation = self
                .next_attachment_generation
                .checked_add(1)
                .expect("frame attachment generation overflow");
            self.frame_attachment_generations
                .insert(frame_id.clone(), self.next_attachment_generation);
            self.frame_sessions
                .insert(frame_id.clone(), replacement_session_id.clone());
            if let Some(record) = self.frames.get_mut(&frame_id) {
                record.session_id = Some(replacement_session_id.clone());
            }
        }
        self.session_frames.remove(detached_session_id);
        self.invalidate_iframe_session_markers(detached_session_id);
        self.forget_frame_session_cache(detached_session_id);
        self.mark_frame_cache_dirty_at_sequence(&replacement_session_id, sequence);
    }

    fn mark_frame_swap_pending(&mut self, frame_id: &str, event_session_id: &str) -> Option<u64> {
        if self.frame_swap_event_completes_adoption(frame_id, event_session_id) {
            // The canonical frame record already represents the adopted child. There is no
            // parent-local frame-tree entry in this state to clear.
            return None;
        }
        let Some(session_id) = self.frame_sessions.get(frame_id).cloned() else {
            return None;
        };
        if session_id != event_session_id {
            // A stale non-owner event must never invalidate whichever session currently owns the
            // frame, even when it cannot be certified as the parent half of live-child adoption.
            return None;
        }
        let Some(generation) = self.frame_attachment_generations.remove(frame_id) else {
            return None;
        };
        self.next_attachment_generation = self
            .next_attachment_generation
            .checked_add(1)
            .expect("frame attachment generation overflow");
        self.invalidate_iframe_session_markers(&session_id);
        self.frame_session_errors.remove(frame_id);
        let link = FrameSwapLink {
            losing_session_id: session_id,
            losing_generation: generation,
            successor_generation: None,
            losing_detach_consumed: false,
        };
        let continues_lineage = self.frame_swaps.get(frame_id).is_some_and(|swap| {
            swap.lineage
                .last()
                .is_some_and(|previous| previous.successor_generation == Some(generation))
        });
        if continues_lineage {
            let swap = self
                .frame_swaps
                .get_mut(frame_id)
                .expect("continuing swap lineage");
            swap.lineage.push(link);
            swap.successor_ready = false;
        } else {
            self.frame_swaps.insert(
                frame_id.to_string(),
                FrameSwapState {
                    lineage: vec![link],
                    successor_ready: false,
                },
            );
        }
        self.notify_session_update();
        Some(generation)
    }

    fn detach_session(&mut self, detached_session_id: &str) {
        self.detach_session_at_sequence(detached_session_id, None);
    }

    fn detach_session_at_sequence(&mut self, detached_session_id: &str, sequence: Option<u64>) {
        for session_id in self.session_ids() {
            self.mark_frame_cache_dirty_at_sequence(&session_id, sequence);
        }
        if let Some(frame_id) = self.frame_swaps.iter().find_map(|(frame_id, swap)| {
            (!swap.successor_ready
                && swap
                    .lineage
                    .iter()
                    .any(|link| link.losing_session_id == detached_session_id))
            .then(|| frame_id.clone())
        }) {
            let current_generation = self.frame_attachment_generations.get(&frame_id).copied();
            let current_session_matches = self
                .frame_sessions
                .get(&frame_id)
                .is_some_and(|session_id| session_id == detached_session_id);
            let current_is_same_id_successor = current_session_matches
                && current_generation.is_some()
                && self.frame_swaps.get(&frame_id).is_some_and(|swap| {
                    swap.lineage
                        .last()
                        .is_some_and(|link| link.successor_generation == current_generation)
                });
            let swap = self
                .frame_swaps
                .get_mut(&frame_id)
                .expect("matched swap lineage");
            if let Some(link) = swap.lineage.iter_mut().find(|link| {
                link.losing_session_id == detached_session_id && !link.losing_detach_consumed
            }) {
                // Only the first detach for each losing edge is non-terminal. When no successor
                // owns the frame yet, remove the dead forward association as well as its reverse
                // ownership; the frame metadata and lineage remain available for the successor.
                link.losing_detach_consumed = true;
                if current_session_matches && current_generation.is_none() {
                    self.frame_sessions.remove(&frame_id);
                    if let Some(record) = self.frames.get_mut(&frame_id) {
                        record.session_id = None;
                    }
                }
                // Consuming a descendant's losing edge is non-terminal for that descendant's
                // waiters, but it must not bypass ordinary cleanup for the detaching session's
                // own root and other mappings. A same-ID successor is the sole exception: that
                // generation is live ownership, not residue from the losing edge.
                if !current_is_same_id_successor {
                    self.remap_detached_session_ownership(detached_session_id, sequence);
                }
                self.forget_frame_session_cache(detached_session_id);
                self.notify_session_update();
                return;
            }
            if current_is_same_id_successor {
                self.invalidate_frame_attachment(&frame_id);
            }
            self.forget_frame_session_cache(detached_session_id);
            self.notify_session_update();
            return;
        }
        self.remap_detached_session_ownership(detached_session_id, sequence);
        self.notify_session_update();
    }

    fn record_frame(
        &mut self,
        frame_id: String,
        parent_id: Option<String>,
        name: Option<String>,
        url: Option<String>,
        event_session_id: String,
    ) {
        let inferred_new_owner = !self.frame_sessions.contains_key(&frame_id)
            && !self
                .frame_swaps
                .get(&frame_id)
                .is_some_and(|swap| !swap.successor_ready);
        let session_id = if let Some(session_id) = self.frame_sessions.get(&frame_id) {
            Some(session_id.clone())
        } else if self
            .frame_swaps
            .get(&frame_id)
            .is_some_and(|swap| !swap.successor_ready)
        {
            // Frame-tree and navigation observations may arrive during the dead-session window.
            // They update metadata but cannot make an event session the swap successor; only an
            // explicit Target attachment may restore the routable forward association.
            None
        } else {
            self.next_attachment_generation = self
                .next_attachment_generation
                .checked_add(1)
                .expect("frame attachment generation overflow");
            self.frame_attachment_generations
                .insert(frame_id.clone(), self.next_attachment_generation);
            self.frame_sessions
                .insert(frame_id.clone(), event_session_id.clone());
            Some(event_session_id.clone())
        };
        let entry = self
            .frames
            .entry(frame_id.clone())
            .or_insert_with(|| PageFrameRecord {
                id: frame_id.clone(),
                parent_id: parent_id.clone(),
                name: String::new(),
                url: String::new(),
                session_id: session_id.clone(),
                name_stamp: None,
                url_stamp: None,
            });
        entry.parent_id = parent_id.clone().or_else(|| entry.parent_id.clone());
        let metadata_stamp = FrameMetadataStamp {
            attachment_generation: (self.frame_sessions.get(&frame_id).map(String::as_str)
                == Some(event_session_id.as_str()))
            .then(|| self.frame_attachment_generations.get(&frame_id).copied())
            .flatten(),
            session_id: event_session_id,
            source: FrameMetadataSource::FrameObservation,
        };
        if let Some(name) = name {
            entry.name = name;
            entry.name_stamp = Some(metadata_stamp.clone());
        }
        if let Some(url) = url {
            entry.url = url;
            entry.url_stamp = Some(metadata_stamp);
        }
        entry.session_id = session_id;

        if inferred_new_owner {
            advance_lifetime_counter(&mut self.frame_ownership_generation);
        }

        if let Some(parent_id) = parent_id {
            let children = self.child_order.entry(parent_id).or_default();
            if !children.iter().any(|existing| existing == &frame_id) {
                children.push(frame_id);
            }
        }
    }

    fn seed_attached_frame_metadata(
        &mut self,
        frame_id: &str,
        session_pin: &FrameSessionPin,
        name: Option<String>,
        url: Option<String>,
    ) {
        let Some(entry) = self.frames.get_mut(frame_id) else {
            return;
        };
        let is_fresher_navigation = |stamp: Option<&FrameMetadataStamp>| {
            stamp.is_some_and(|stamp| {
                stamp.source == FrameMetadataSource::FrameObservation
                    && stamp.session_id == session_pin.session_id
                    && (stamp.attachment_generation.is_none()
                        || stamp.attachment_generation == Some(session_pin.generation))
            })
        };
        let target_stamp = FrameMetadataStamp {
            session_id: session_pin.session_id.clone(),
            attachment_generation: Some(session_pin.generation),
            source: FrameMetadataSource::TargetInfo,
        };
        // TargetInfo is the attachment-window baseline. It replaces metadata from an older
        // owner/generation, while a frame-tree or frameNavigated observation already associated
        // with this attachment wins field-by-field and remains authoritative.
        if let Some(name) = name {
            if !is_fresher_navigation(entry.name_stamp.as_ref()) {
                entry.name = name;
                entry.name_stamp = Some(target_stamp.clone());
            }
        }
        if let Some(url) = url {
            if !is_fresher_navigation(entry.url_stamp.as_ref()) {
                entry.url = url;
                entry.url_stamp = Some(target_stamp);
            }
        }
    }

    fn remove_frame_inner(&mut self, frame_id: &str, removed_generations: &mut Vec<u64>) {
        let children = self.child_order.remove(frame_id).unwrap_or_default();
        for child in children {
            self.remove_frame_inner(&child, removed_generations);
        }
        self.frames.remove(frame_id);
        self.frame_loader_ids.remove(frame_id);
        self.invalidate_execution_contexts_for_frame(frame_id);
        if let Some(generation) = self.frame_attachment_generations.get(frame_id).copied() {
            removed_generations.push(generation);
        }
        self.invalidate_frame_attachment(frame_id);
        if self
            .frame_attachment_locks
            .get(frame_id)
            .is_some_and(|attachment_lock| Arc::strong_count(attachment_lock) == 1)
        {
            self.frame_attachment_locks.remove(frame_id);
        }
        for children in self.child_order.values_mut() {
            children.retain(|child| child != frame_id);
        }
    }

    fn remove_frame(&mut self, frame_id: &str) -> Vec<u64> {
        let mut removed_generations = Vec::new();
        self.remove_frame_inner(frame_id, &mut removed_generations);
        self.notify_session_update();
        removed_generations
    }

    #[cfg(test)]

    fn prune_frames_not_in(&mut self, authoritative_frame_ids: &HashSet<String>) -> Vec<u64> {
        let stale_frame_ids = self
            .frames
            .keys()
            .chain(self.frame_sessions.keys())
            .chain(self.frame_attachment_generations.keys())
            .chain(self.frame_attachment_locks.keys())
            .filter(|frame_id| !authoritative_frame_ids.contains(*frame_id))
            .cloned()
            .collect::<HashSet<_>>();
        let mut removed_generations = Vec::new();
        for frame_id in stale_frame_ids {
            self.frames.remove(&frame_id);
            if let Some(generation) = self.frame_attachment_generations.get(&frame_id).copied() {
                removed_generations.push(generation);
            }
            self.invalidate_frame_attachment(&frame_id);
            if self
                .frame_attachment_locks
                .get(&frame_id)
                .is_some_and(|attachment_lock| Arc::strong_count(attachment_lock) == 1)
            {
                self.frame_attachment_locks.remove(&frame_id);
            }
        }
        self.child_order
            .retain(|parent_id, _| authoritative_frame_ids.contains(parent_id));
        for children in self.child_order.values_mut() {
            children.retain(|child_id| authoritative_frame_ids.contains(child_id));
        }
        let stale_session_ids = self
            .session_frames
            .iter()
            .filter_map(|(session_id, frame_id)| {
                (!authoritative_frame_ids.contains(frame_id)
                    || self.frame_sessions.get(frame_id) != Some(session_id))
                .then_some(session_id.clone())
            })
            .collect::<Vec<_>>();
        for session_id in stale_session_ids {
            self.session_frames.remove(&session_id);
            self.invalidate_iframe_session_markers(&session_id);
        }
        self.notify_session_update();
        removed_generations
    }
}

fn resolve_cached_main_frame_url(
    main_frame_id: Option<&str>,
    state: &PageFrameState,
) -> Option<String> {
    let frame_id = main_frame_id?;
    state
        .frames
        .get(frame_id)
        .map(|record| record.url.clone())
        .filter(|url| !url.is_empty())
}

impl PageInner {
    async fn main_frame_id(
        &self,
        client: &CdpClient,
        session_id: &str,
        timeout: Duration,
    ) -> RwResult<String> {
        // The cached id is this page's own root frame. An out-of-process iframe resolves
        // to its own target session whose root is a different frame entirely, so reusing
        // the cache there would hand Page.createIsolatedWorld a frame that session has
        // never heard of — and caching what that session reports would corrupt the page's
        // own id in the other direction.
        let own_session = session_id == self.session_id;
        if !own_session {
            return self
                .frame_state
                .lock()
                .unwrap()
                .session_frames
                .get(session_id)
                .cloned()
                .ok_or_else(|| {
                    RwError::Message(
                        "iframe session did not have an attachment frame id".to_string(),
                    )
                });
        }
        if own_session {
            if let Some(frame_id) = self.main_frame_id.lock().unwrap().clone() {
                return Ok(frame_id);
            }
        }
        let frame_tree = client
            .send("Page.getFrameTree", json!({}), Some(session_id), timeout)
            .await?;
        let frame_id = frame_tree
            .pointer("/frameTree/frame/id")
            .and_then(Value::as_str)
            .ok_or_else(|| RwError::Message("CDP did not return a main frame id".to_string()))?
            .to_string();
        if own_session {
            *self.main_frame_id.lock().unwrap() = Some(frame_id.clone());
        }
        Ok(frame_id)
    }

    fn session_for_frame_id(&self, frame_id: &str) -> RwResult<String> {
        let state = self.frame_state.lock().unwrap();
        if let Some(session_id) = state.frame_sessions.get(frame_id) {
            return Ok(session_id.clone());
        }
        if state.frames.contains_key(frame_id) {
            return Err(RwError::Message(
                "frame session is not currently attached".to_string(),
            ));
        }
        Ok(self.session_id.clone())
    }

    fn cached_main_frame_url(&self) -> Option<String> {
        let main_id = self.main_frame_id.lock().unwrap().clone();
        let state = self.frame_state.lock().unwrap();
        resolve_cached_main_frame_url(main_id.as_deref(), &state)
    }

    fn record_frame_navigation_url(&self, frame_id: &str, url: &str, session_id: &str) {
        self.frame_state.lock().unwrap().record_frame(
            frame_id.to_string(),
            None,
            None,
            Some(url.to_string()),
            session_id.to_string(),
        );
    }

    fn record_main_frame_navigation_url(&self, frame_id: &str, url: &str) {
        *self.main_frame_id.lock().unwrap() = Some(frame_id.to_string());
        self.record_frame_navigation_url(frame_id, url, &self.session_id);
    }

    fn frame_tree_payload(&self) -> Value {
        // Page cache readers never nest these locks. Clone main_frame_id first,
        // release it, then acquire frame_state.
        let cached_root_id = self.main_frame_id.lock().unwrap().clone();
        let state = self.frame_state.lock().unwrap();
        let root_id = cached_root_id.or_else(|| {
            state
                .frames
                .values()
                .find(|record| record.parent_id.is_none())
                .map(|record| record.id.clone())
        });
        let Some(root_id) = root_id else {
            return json!({ "frameTree": Value::Null });
        };
        let Some(root) = build_frame_tree_node(&state, &root_id) else {
            return json!({ "frameTree": Value::Null });
        };
        json!({ "frameTree": root })
    }
}

fn build_frame_tree_node(state: &PageFrameState, frame_id: &str) -> Option<Value> {
    let mut visited = HashSet::new();
    build_frame_tree_node_guarded(state, frame_id, &mut visited, 0)
}

fn build_frame_tree_node_guarded(
    state: &PageFrameState,
    frame_id: &str,
    visited: &mut HashSet<String>,
    depth: usize,
) -> Option<Value> {
    if depth >= MAX_FRAME_TREE_DEPTH || !visited.insert(frame_id.to_string()) {
        return None;
    }
    let record = state.frames.get(frame_id)?;
    let mut frame = json!({
        "id": record.id,
        "url": record.url,
        "name": record.name,
    });
    if let Some(parent_id) = &record.parent_id {
        frame["parentId"] = Value::String(parent_id.clone());
    }
    let child_ids = state.child_order.get(frame_id).cloned().unwrap_or_default();
    let mut child_frames = Vec::new();
    for child_id in child_ids {
        if let Some(child) = build_frame_tree_node_guarded(state, &child_id, visited, depth + 1) {
            child_frames.push(child);
        }
    }
    let mut node = json!({ "frame": frame });
    if !child_frames.is_empty() {
        node["childFrames"] = Value::Array(child_frames);
    }
    Some(node)
}

