#[cfg(feature = "python")]
impl PyPage {
    fn navigate_history(
        &self,
        offset: i64,
        wait_until: Option<&str>,
        timeout_ms: Option<f64>,
    ) -> PyResult<String> {
        let page = Arc::clone(&self.inner);
        let wait_until = wait_until.unwrap_or("load").to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        let client = Arc::clone(&browser.client);
        let session_id = page.session_id.clone();
        browser
            .block_on(async move {
                let deadline = OperationDeadline::new(timeout);
                let history = client
                    .send(
                        "Page.getNavigationHistory",
                        json!({}),
                        Some(&session_id),
                        deadline.remaining()?,
                    )
                    .await?;
                let current_index = history
                    .get("currentIndex")
                    .and_then(Value::as_i64)
                    .ok_or_else(|| {
                        RwError::Message(
                            "CDP did not return a navigation history index".to_string(),
                        )
                    })?;
                let target_index = current_index + offset;
                let entries = history
                    .get("entries")
                    .and_then(Value::as_array)
                    .ok_or_else(|| {
                        RwError::Message(
                            "CDP did not return navigation history entries".to_string(),
                        )
                    })?;
                if target_index < 0 || target_index as usize >= entries.len() {
                    return Ok(Value::Null.to_string());
                }
                let navigation_frame_id = if wait_until == "commit" {
                    page.main_frame_id.lock().unwrap().clone()
                } else {
                    Some(
                        page.main_frame_id(&client, &session_id, deadline.remaining()?)
                            .await?,
                    )
                };
                let entry_id = entries[target_index as usize]
                    .get("id")
                    .and_then(Value::as_i64)
                    .ok_or_else(|| {
                        RwError::Message(
                            "CDP did not return a navigation history entry id".to_string(),
                        )
                    })?;
                let target_url = entries[target_index as usize]
                    .get("url")
                    .and_then(Value::as_str)
                    .map(ToString::to_string);
                let (mut events, event_cursor) = client.subscribe_with_cursor();
                let restore_initiation_cursor = send_history_entry_navigation(
                    &client,
                    entry_id,
                    &session_id,
                    deadline.remaining()?,
                )
                .await?;
                let response = wait_for_navigation(
                    &client,
                    &mut events,
                    event_cursor,
                    Some(restore_initiation_cursor),
                    &session_id,
                    &wait_until,
                    navigation_frame_id.as_deref(),
                    None,
                    target_url.as_deref(),
                    target_url.as_deref(),
                    true,
                    if offset < 0 {
                        "Page.go_back"
                    } else {
                        "Page.go_forward"
                    },
                    deadline,
                )
                .await?;
                Ok(response.response.unwrap_or(Value::Null).to_string())
            })
            .map_err(|error| normalize_navigation_timeout(error, OperationDeadline::new(timeout)))
            .map_err(py_err)
    }

    fn evaluate_expression(&self, expression: &str, timeout_ms: Option<f64>) -> RwResult<String> {
        evaluate_expression_for_page(Arc::clone(&self.inner), expression.to_string(), timeout_ms)
    }

    fn evaluate_handle_expression(
        &self,
        expression: &str,
        timeout_ms: Option<f64>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let expression = expression.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        let client = Arc::clone(&browser.client);
        let session_id = page.session_id.clone();
        browser.block_on(async move {
            let result = client
                .send(
                    "Runtime.evaluate",
                    json!({
                        "expression": expression,
                        "awaitPromise": true,
                        "returnByValue": false,
                        "userGesture": true,
                    }),
                    Some(&session_id),
                    timeout,
                )
                .await?;
            runtime_result_to_remote_object_with_session(&result, &session_id)
        })
    }

    fn call_function_in_default_context(
        &self,
        function_declaration: &str,
        arguments: Option<Value>,
        timeout_ms: Option<f64>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let function_declaration = function_declaration.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        let client = Arc::clone(&browser.client);
        let session_id = page.session_id.clone();
        let realm_identity = page
            .main_frame_id
            .lock()
            .unwrap()
            .as_deref()
            .map(|frame_id| format!("frame:{frame_id}"));
        let realm = client.serializer_realm_key(&session_id, realm_identity.as_deref());
        browser.block_on(async move {
            let result = call_function_in_context_with_serialized_result_before(
                &client,
                &realm,
                None,
                &function_declaration,
                arguments.as_ref(),
                OperationDeadline::new(timeout),
            )
            .await?;
            runtime_serialized_result_to_json(&result)
        })
    }

    fn call_function_on_handle(
        &self,
        object_id: &str,
        function_declaration: &str,
        arguments: Option<Value>,
        return_by_value: bool,
        timeout_ms: Option<f64>,
        session_id: Option<&str>,
        realm_identity: Option<&str>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let object_id = object_id.to_string();
        let function_declaration = function_declaration.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        let client = Arc::clone(&browser.client);
        let session_id = session_id
            .map(ToString::to_string)
            .unwrap_or_else(|| page.session_id.clone());
        let realm = client.serializer_realm_key(&session_id, realm_identity);
        browser.block_on(async move {
            let result = if return_by_value {
                call_function_with_serialized_result_before(
                    &client,
                    &realm,
                    &object_id,
                    &function_declaration,
                    arguments.as_ref(),
                    OperationDeadline::new(timeout),
                )
                .await?
            } else {
                let mut params = json!({
                    "objectId": object_id,
                    "functionDeclaration": function_declaration,
                    "awaitPromise": true,
                    "returnByValue": false,
                    "userGesture": true,
                });
                if let Some(arguments) = arguments {
                    params["arguments"] = arguments;
                }
                client
                    .send("Runtime.callFunctionOn", params, Some(&session_id), timeout)
                    .await?
            };
            if return_by_value {
                runtime_serialized_result_to_json(&result)
            } else {
                runtime_result_to_remote_object_with_session(&result, &session_id)
            }
        })
    }

    fn evaluate_locator(
        &self,
        locator_json: &str,
        index: usize,
        body: &str,
        timeout_ms: Option<f64>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let locator_json = locator_json.to_string();
        let body = body.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        browser.block_on(async move {
            evaluate_locator_for_page(page, locator_json, index, body, timeout).await
        })
    }

    fn evaluate_locator_action(
        &self,
        locator_json: &str,
        index: usize,
        body: &str,
        timeout_ms: Option<f64>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let locator_json = locator_json.to_string();
        let body = body.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        browser.block_on(async move {
            evaluate_locator_action_for_page(page, locator_json, index, body, timeout).await
        })
    }

    fn evaluate_locator_dispatch(
        &self,
        locator_json: &str,
        index: usize,
        prepare_body: &str,
        dispatch_body: &str,
        timeout_ms: Option<f64>,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let locator_json = locator_json.to_string();
        let prepare_body = prepare_body.to_string();
        let dispatch_body = dispatch_body.to_string();
        let timeout = BrowserInner::command_timeout(timeout_ms);
        let browser = Arc::clone(&page.browser);
        browser.block_on(async move {
            evaluate_locator_dispatch_for_page(
                page,
                locator_json,
                index,
                prepare_body,
                dispatch_body,
                timeout,
            )
            .await
        })
    }

    fn assert_locator_sync(
        &self,
        locator_json: &str,
        index: usize,
        matcher_json: &str,
        timeout_ms: f64,
        polling_interval_ms: f64,
    ) -> RwResult<String> {
        let page = Arc::clone(&self.inner);
        let locator_json = locator_json.to_string();
        let matcher_json = matcher_json.to_string();
        let timeout = locator_assertion_duration(timeout_ms, "timeout", true)?;
        let polling_interval =
            locator_assertion_duration(polling_interval_ms, "polling interval", false)?;
        let browser = Arc::clone(&page.browser);
        browser.block_on(async move {
            assert_locator_for_page(
                page,
                locator_json,
                index,
                matcher_json,
                timeout,
                polling_interval,
            )
            .await
        })
    }
}

fn launch_chromium_with_options(options: LaunchOptions) -> RwResult<Arc<BrowserInner>> {
    launch_chromium_with_options_cancellation(
        options,
        None,
        None,
        Some(startup_timing::EntryPoint::RustNative),
    )
}

fn launch_chromium_with_options_token(
    options: LaunchOptions,
    cancel: CancelToken,
) -> RwResult<Arc<BrowserInner>> {
    launch_chromium_with_options_cancellation(
        options,
        Some(cancel.atomic_flag()),
        Some(cancel),
        Some(startup_timing::EntryPoint::RustNative),
    )
}

fn launch_chromium_with_options_cancellation(
    mut options: LaunchOptions,
    cancelled: Option<Arc<AtomicBool>>,
    cancel: Option<CancelToken>,
    entrypoint: Option<startup_timing::EntryPoint>,
) -> RwResult<Arc<BrowserInner>> {
    let startup_probe = startup_timing::StartupProbe::from_env(
        entrypoint.unwrap_or(startup_timing::EntryPoint::Unknown),
    );
    if options.timeout.is_none() {
        options.timeout = Some(30_000.0);
    }
    let runtime = startup_timing::measure_phase(
        startup_probe.as_deref(),
        startup_timing::Phase::RuntimeCreate,
        Some(startup_timing::ParentPhase::BrowserLaunch),
        || {
            tokio::runtime::Builder::new_multi_thread()
                .enable_all()
                .worker_threads(2)
                .build()
                .map_err(|error| RwError::Message(error.to_string()))
        },
    )?;
    let timeout = BrowserInner::command_timeout(options.timeout);
    let (mut child, profile_dir, transport, single_process_fallback) = launch_chromium_process(
        &options,
        &runtime,
        timeout,
        cancelled.clone(),
        startup_probe.as_deref(),
    )?;
    let ws_endpoint = transport.endpoint_label();
    let client_result = startup_timing::measure_phase(
        startup_probe.as_deref(),
        startup_timing::Phase::TransportConnect,
        Some(startup_timing::ParentPhase::BrowserLaunch),
        || match transport {
            LaunchedCdpTransport::WebSocket(endpoint) => runtime.block_on(async {
                if let Some(cancelled) = cancelled.clone() {
                    tokio::select! {
                        result = CdpClient::connect(&endpoint) => result,
                        () = wait_for_launch_cancellation(cancelled) => {
                            Err(RwError::Message("browser launch was cancelled".to_string()))
                        }
                    }
                } else {
                    CdpClient::connect(&endpoint).await
                }
            }),
            #[cfg(unix)]
            LaunchedCdpTransport::Pipe { read, write } => {
                runtime.block_on(CdpClient::connect_pipe(read, write))
            }
        },
    );
    let client = match client_result {
        Ok(client) => client,
        Err(error) => {
            let _ = child.kill();
            let _ = child.wait();
            return Err(error);
        }
    };
    if let Err(error) = start_service_worker_stealth_auto_attach_cancelable(
        &runtime,
        Arc::clone(&client),
        Duration::from_secs(5),
        cancel,
        startup_probe.as_deref(),
    ) {
        client.close();
        let _ = child.kill();
        let _ = child.wait();
        return Err(error);
    }
    let browser_probe = startup_probe.clone();
    startup_timing::measure_phase(
        startup_probe.as_deref(),
        startup_timing::Phase::BrowserReturn,
        Some(startup_timing::ParentPhase::BrowserLaunch),
        || {
            let browser = Arc::new(BrowserInner {
                runtime: OwnedRuntime::new(runtime),
                client,
                startup_probe: browser_probe,
                process: Mutex::new(Some(child)),
                profile_dir: Mutex::new(profile_dir),
                owned: true,
                ws_endpoint,
                stealth_user_agent_override: Mutex::new(None),
                keyboard_platform: BrowserKeyboardPlatformState::default(),
                single_process_fallback,
                lifecycle: Arc::new(CloseLifecycle::new()),
                attached_pages: AttachedPageRegistry::default(),
                next_native_network_index: AtomicU64::new(1),
            });
            if launch_was_cancelled(cancelled.as_ref()) {
                let _ = close_browser_blocking(Arc::clone(&browser));
                return Err(RwError::Message("browser launch was cancelled".to_string()));
            }
            telemetry::record_engine_launched(&browser.runtime);
            Ok(browser)
        },
    )
}

fn launch_was_cancelled(cancelled: Option<&Arc<AtomicBool>>) -> bool {
    cancelled
        .map(|cancelled| cancelled.load(Ordering::SeqCst))
        .unwrap_or(false)
}

async fn wait_for_launch_cancellation(cancelled: Arc<AtomicBool>) {
    while !cancelled.load(Ordering::SeqCst) {
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
}

#[cfg(feature = "python")]
#[pyfunction]
fn launch_chromium(py: Python<'_>, options_json: &str) -> PyResult<PyBrowser> {
    let options = parse_python_launch_options(options_json)?;
    let inner = py
        .detach(move || {
            launch_chromium_with_options_cancellation(
                options,
                None,
                None,
                Some(startup_timing::EntryPoint::PythonSync),
            )
        })
        .map_err(py_err)?;
    Ok(PyBrowser { inner })
}

#[cfg(feature = "python")]
#[pyfunction]
fn launch_chromium_async(py: Python<'_>, options_json: &str) -> PyResult<Py<PyAny>> {
    let options = parse_python_launch_options(options_json)?;
    python_future_on_thread(
        py,
        move |cancelled| {
            Ok(PyBrowser {
                inner: launch_chromium_with_options_cancellation(
                    options,
                    Some(cancelled),
                    None,
                    Some(startup_timing::EntryPoint::PythonAsync),
                )?,
            })
        },
        |py, browser| Ok(Py::new(py, browser)?.into_any()),
    )
}

#[cfg(feature = "test-support")]
type ConnectStageObserver = Arc<dyn Fn(&'static str, Duration) + Send + Sync>;

#[cfg(feature = "test-support")]
#[derive(Clone, Default)]
struct ConnectTestOptions {
    observer: Option<ConnectStageObserver>,
    tls_ca_pem: Option<String>,
}

#[cfg(feature = "test-support")]
impl ConnectTestOptions {
    fn observe(&self, stage: &'static str, remaining: Duration) {
        if let Some(observer) = &self.observer {
            observer(stage, remaining);
        }
    }
}

// This test-only one-shot slot does not support concurrent arm-and-connect
// sequences. Test helpers must serialize each arm with its matching connect.
#[cfg(feature = "test-support")]
static CONNECT_TEST_OPTIONS: LazyLock<Mutex<Option<ConnectTestOptions>>> =
    LazyLock::new(|| Mutex::new(None));

#[cfg(feature = "test-support")]
fn install_connect_test_options(options: ConnectTestOptions) {
    let mut slot = CONNECT_TEST_OPTIONS
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    *slot = Some(options);
}

#[cfg(feature = "test-support")]
fn take_connect_test_options() -> Option<ConnectTestOptions> {
    CONNECT_TEST_OPTIONS
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take()
}
#[cfg(feature = "test-support")]
fn connect_stage_observer(observer: Option<Py<PyAny>>) -> Option<ConnectStageObserver> {
    observer.map(|observer| {
        Arc::new(move |stage: &'static str, remaining: Duration| {
            Python::attach(|py| {
                let _ = observer.call1(py, (stage, remaining.as_secs_f64()));
            });
        }) as ConnectStageObserver
    })
}

#[cfg(feature = "python")]
#[pyfunction]
#[pyo3(signature = (endpoint, timeout_ms=None, headers_json=None))]
fn connect_over_cdp(
    py: Python<'_>,
    endpoint: &str,
    timeout_ms: Option<f64>,
    headers_json: Option<&str>,
) -> PyResult<PyBrowser> {
    #[cfg(feature = "test-support")]
    CONNECT_NATIVE_BINDING_COUNT.fetch_add(1, Ordering::SeqCst);
    let timeout = BrowserInner::command_timeout(timeout_ms);
    let headers = parse_header_pairs(headers_json).map_err(py_err)?;
    let endpoint = endpoint.to_string();
    let inner = py
        .detach(move || connect_browser_over_cdp_sanitized(endpoint, headers, timeout, None))
        .map_err(py_err)?;
    Ok(PyBrowser { inner })
}

#[cfg(feature = "test-support")]
#[pyfunction(name = "_test_set_connect_options")]
#[pyo3(signature = (observer=None, ca_pem=None))]
fn test_set_connect_options(observer: Option<Py<PyAny>>, ca_pem: Option<&str>) {
    install_connect_test_options(ConnectTestOptions {
        observer: connect_stage_observer(observer),
        tls_ca_pem: ca_pem.map(str::to_string),
    });
}

#[cfg(feature = "test-support")]
#[pyfunction(name = "_test_connect_over_cdp")]
#[pyo3(signature = (endpoint, observer, timeout_ms=None, headers_json=None, ca_pem=None))]
fn test_connect_over_cdp(
    py: Python<'_>,
    endpoint: &str,
    observer: Py<PyAny>,
    timeout_ms: Option<f64>,
    headers_json: Option<&str>,
    ca_pem: Option<&str>,
) -> PyResult<PyBrowser> {
    let timeout = BrowserInner::command_timeout(timeout_ms);
    let headers = parse_header_pairs(headers_json).map_err(py_err)?;
    let endpoint = endpoint.to_string();
    let options = ConnectTestOptions {
        observer: connect_stage_observer(Some(observer)),
        tls_ca_pem: ca_pem.map(str::to_string),
    };
    let inner = py
        .detach(move || {
            install_connect_test_options(options);
            connect_browser_over_cdp_sanitized(endpoint, headers, timeout, None)
        })
        .map_err(py_err)?;
    Ok(PyBrowser { inner })
}

